function applyEditorialRevision(guide, revision) {
  guide.standfirst = revision.standfirst;
  if (revision.editorialAngle) guide.editorialAngle = revision.editorialAngle;
  for (const [id, paragraphs] of Object.entries(revision.sections)) {
    byId(guide.sections, id, "section").paragraphs = paragraphs;
  }
  guide.tour.summary = revision.tour.summary;
  guide.tour.suitability = revision.tour.suitability;
  for (const [id, body] of Object.entries(revision.tour.steps)) {
    byId(guide.tour.steps, id, "tour step").body = body;
  }
  for (const [id, body] of Object.entries(revision.fieldNotes)) {
    byId(guide.fieldNotes, id, "field note").body = body;
  }
  revision.faq.forEach((item, index) => {
    guide.faq[index].question = item.question;
    guide.faq[index].answer = item.answer;
  });
}

