function reviseIsleOfSark(guide) {
  applyEditorialRevision(guide, {
    standfirst: {
      en: "Sark's dark-sky reputation does not make every coastal path an observing site. The island's visitor service documents two practical choices: year-round telescope sessions arranged at the Dachinger Observatory and stargazing from the grass of the bookable La Valette campsite. Keep those models separate. An observatory confirmation covers its guided programme; a campsite reservation covers the assigned camping footprint, not the lighthouse lookout, private land or a late walk along the coast.",
      de: "Sarks Ruf für dunklen Himmel macht nicht jeden Küstenweg zum Beobachtungsort. Der offizielle Besucherdienst dokumentiert zwei praktische Möglichkeiten: ganzjährige Teleskopsitzungen nach Vereinbarung am Dachinger Observatory und Sternbeobachtung auf der Wiese des buchbaren Campingplatzes La Valette. Halte beide Modelle getrennt. Eine Observatoriumsbestätigung gilt für das geführte Programm; eine Campingreservierung für die zugewiesene Stellfläche und nicht für Leuchtturmaussicht, Privatland oder einen späten Küstenweg.",
    },
    editorialAngle: {
      en: "Choose either a confirmed Dachinger session or a booked night at La Valette. The exact visitor footprints remove any need to invent a cliff-edge fallback on an island where darkness and access are not the same thing.",
      de: "Wähle entweder eine bestätigte Dachinger-Sitzung oder eine gebuchte Nacht auf La Valette. Die genauen Besucherflächen machen einen erfundenen Klippenersatz unnötig, denn Dunkelheit und Zugang sind auf der Insel nicht dasselbe.",
    },
    sections: {
      "isle-of-sark-where": {
        en: [
          "The Dachinger Observatory is a named facility used by the Sark Astronomy Society for telescope sessions throughout the year. The Visitor Centre handles the published booking route, so a confirmed time defines when the observatory is a visitor place. Its mapped footprint supports arrival for that session only; it does not imply that the building, surrounding lanes or nearby ground remain available for independent observing outside the programme.",
          "La Valette is different because the official visitor listing identifies it as a permitted campsite and specifically promotes viewing constellations from its grass. That makes a booked pitch a defensible overnight observing base. Stay within the campsite layout and ordinary guest rules. The listing does not extend the pitch to neighbouring coast, private property or another scenic point after dark.",
        ],
        de: [
          "Das Dachinger Observatory ist eine benannte Einrichtung, an der die Sark Astronomy Society ganzjährig Teleskopsitzungen anbietet. Der Visitor Centre bildet den veröffentlichten Buchungsweg; deshalb legt eine bestätigte Uhrzeit fest, wann das Observatorium Besucherort ist. Der kartierte Grundriss unterstützt nur die Anreise zu dieser Sitzung und bedeutet nicht, dass Gebäude, umliegende Wege oder Nachbarflächen außerhalb des Programms selbstständig nutzbar bleiben.",
          "La Valette funktioniert anders, weil der offizielle Besuchereintrag den Ort als erlaubten Campingplatz bezeichnet und ausdrücklich das Betrachten von Sternbildern von seiner Wiese bewirbt. Ein gebuchter Stellplatz ist damit eine belastbare Übernachtungsbasis. Bleibe innerhalb des Campinglayouts und der normalen Gästeregeln. Der Eintrag erweitert die Fläche nicht auf Küste, Privatgrund oder einen anderen Aussichtspunkt nach Einbruch der Dunkelheit.",
        ],
      },
      "isle-of-sark-conditions": {
        en: [
          "For an observatory night, use the confirmed programme time and any weather decision supplied through the official booking channel. A year-round offer still depends on the actual session and safe operation. If the telescope visit cannot run, the responsible result is postponement. A dark island forecast does not convert the observatory lane or a coastal footpath into a substitute venue.",
          "At La Valette, judge wind, rain and ground condition for a grass campsite rather than for Sark in general. Arrive before dark, identify the assigned pitch, facilities and route back to shelter, and keep observation beside the booked accommodation. The campsite's stargazing description supports use by guests; it does not remove pitch rules or make exposed coastal walking part of the night plan.",
        ],
        de: [
          "Für einen Observatoriumsabend gelten bestätigte Programmzeit und die über den offiziellen Buchungsweg mitgeteilte Wetterentscheidung. Ein ganzjähriges Angebot hängt trotzdem von der konkreten Sitzung und sicherem Betrieb ab. Kann der Teleskopbesuch nicht stattfinden, wird verschoben. Eine dunkle Inselprognose verwandelt weder Observatoriumsweg noch Küstenpfad in einen Ersatzort.",
          "Auf La Valette beurteilst du Wind, Regen und Boden für einen Gras-Campingplatz statt allgemein für Sark. Komme vor der Dunkelheit an, erkenne zugewiesenen Stellplatz, Einrichtungen und Schutzweg und beobachte neben der gebuchten Unterkunft. Die Stargazing-Beschreibung unterstützt die Nutzung durch Gäste, hebt aber weder Stellplatzregeln auf noch macht sie exponierte Küstenwanderungen zum Nachtplan.",
        ],
      },
    },
    tour: {
      summary: {
        en: "For a guided night, obtain a confirmed Dachinger Observatory session through the official visitor route, arrive at the stated time and remain with the telescope programme until it ends. For an independent accommodation night, book La Valette and observe from the grass beside the assigned pitch. Never combine the two or continue to a lighthouse, coastal path or private field.",
        de: "Für einen geführten Abend bestätigst du eine Dachinger-Sitzung über den offiziellen Besucherweg, kommst zur angegebenen Zeit und bleibst bis zum Ende beim Teleskopprogramm. Für eine selbstständige Übernachtungsnacht buchst du La Valette und beobachtest von der Wiese am zugewiesenen Stellplatz. Verbinde beide nie und gehe danach weder zu Leuchtturm noch Küstenpfad oder Privatfeld.",
      },
      suitability: {
        en: "Suitable for confirmed observatory participants or registered campsite guests who can keep the entire night inside one authorised visitor footprint and accept weather cancellation without an improvised coastal alternative.",
        de: "Geeignet für bestätigte Observatoriumsteilnehmer oder registrierte Campinggäste, die die gesamte Nacht auf einer autorisierten Besucherfläche bleiben und Wetterabsagen ohne improvisierten Küstenersatz akzeptieren.",
      },
      steps: {
        "isle-of-sark-check": { en: "Decide between the observatory programme and La Valette before travel. Retain the Dachinger confirmation or the campsite booking and check weather for that exact use. The island's dark-sky status is context, not permission to add the lighthouse, a private field or an unverified shore path.", de: "Entscheide vor der Fahrt zwischen Observatoriumsprogramm und La Valette. Speichere Dachinger-Bestätigung oder Campingbuchung und prüfe das Wetter für genau diese Nutzung. Der Dark-Sky-Status der Insel ist Kontext und keine Erlaubnis, Leuchtturm, Privatfeld oder ungeprüften Küstenweg hinzuzufügen." },
        "isle-of-sark-arrive": { en: "Reach the named facility while its entrance, paths and boundaries are visible. Check in for the telescope session or settle only on the assigned La Valette pitch. Carry equipment within that footprint and do not use a scenic map point as an unloading or overflow area.", de: "Erreiche die benannte Einrichtung, solange Eingang, Wege und Grenzen sichtbar sind. Melde dich zur Teleskopsitzung an oder richte dich ausschließlich auf dem zugewiesenen La-Valette-Stellplatz ein. Trage Ausrüstung innerhalb dieser Fläche und nutze keinen schönen Kartenpunkt zum Entladen oder Ausweichen." },
        "isle-of-sark-observe": { en: "At Dachinger, follow the astronomy society's telescope and lighting instructions. At La Valette, keep lamps and equipment beside the booked pitch and protect other campers' darkness. Neither arrangement supports moving onto nearby paths or private ground to widen the horizon.", de: "Folge im Dachinger Observatory den Teleskop- und Lichtanweisungen der Astronomy Society. Halte auf La Valette Lampen und Ausrüstung am gebuchten Stellplatz und schütze die Dunkelheit anderer Gäste. Keine Regelung erlaubt den Wechsel auf nahe Wege oder Privatgrund für einen weiteren Horizont." },
        "isle-of-sark-leave": { en: "End with the programme's instructed departure or by packing everything back into the La Valette pitch. Do not turn the return into a night walk to another island landmark. The complete plan is one confirmed facility followed by shelter at the booked base or a direct lawful return.", de: "Beende den Abend mit der angewiesenen Programmabreise oder indem du alles auf dem La-Valette-Stellplatz verstaust. Mache aus dem Rückweg keinen Nachtspaziergang zu einer weiteren Inselmarke. Der vollständige Plan besteht aus einer bestätigten Einrichtung und danach Schutz an der gebuchten Basis oder direkter legaler Rückkehr." },
      },
    },
    fieldNotes: {
      "isle-of-sark-access-note": { en: "Official visitor sources support contact-based Dachinger sessions and booked camping at La Valette. They do not support observing overflow at the lighthouse, on coastal paths or on private land, even when those places appear darker on a map.", de: "Offizielle Besucherquellen belegen vereinbarte Dachinger-Sitzungen und gebuchtes Camping auf La Valette. Sie belegen keinen Beobachtungsüberlauf am Leuchtturm, auf Küstenwegen oder Privatland, auch wenn diese Orte auf Karten dunkler wirken." },
      "isle-of-sark-weather-note": { en: "Sark's maritime exposure can change a telescope session and a grass campsite differently. Follow the observatory's programme decision or judge the booked pitch conditions; do not use good island-wide darkness as evidence that an exposed path is safe.", de: "Sarks maritime Exposition kann Teleskopsitzung und Gras-Campingplatz unterschiedlich verändern. Folge der Programmentscheidung des Observatoriums oder beurteile den gebuchten Stellplatz; gute inselweite Dunkelheit belegt keinen sicheren exponierten Pfad." },
      "isle-of-sark-light-note": { en: "Both choices depend on shared darkness. Use the level requested by observatory staff or a brief shielded red lamp at the campsite, and prepare screens before other participants or campers begin adapting.", de: "Beide Optionen hängen von gemeinsam erlebter Dunkelheit ab. Nutze die vom Observatorium verlangte Stufe oder kurzes abgeschirmtes Rotlicht am Campingplatz und bereite Displays vor der Dunkeladaption anderer Teilnehmer oder Camper vor." },
    },
    faq: [
      { question: { en: "Can visitors use the Dachinger Observatory without a confirmed session?", de: "Können Besucher das Dachinger Observatory ohne bestätigte Sitzung nutzen?" }, answer: { en: "The official visitor service describes year-round telescope sessions arranged through the Visitor Centre or Sark Astronomy Society. That supports attendance at a confirmed programme, not independent entry between sessions. If no appointment is available, postpone rather than observing from the entrance or nearby land.", de: "Der offizielle Besucherdienst beschreibt ganzjährige Teleskopsitzungen, die über Visitor Centre oder Sark Astronomy Society vereinbart werden. Das belegt die Teilnahme an einem bestätigten Programm und keinen selbstständigen Zutritt dazwischen. Ist kein Termin verfügbar, verschiebe statt am Eingang oder auf Nachbarland zu beobachten." } },
      { question: { en: "Does a La Valette booking include the nearby coast?", de: "Umfasst eine La-Valette-Buchung die nahe Küste?" }, answer: { en: "No. The official listing supports constellation viewing from the campsite grass, which makes the assigned pitch the observing footprint. It does not grant night use of coastal paths, a lighthouse lookout or private property. Keep equipment and light within the campsite and follow its guest rules.", de: "Nein. Der offizielle Eintrag unterstützt Sternbildbeobachtung von der Campingwiese; damit ist der zugewiesene Stellplatz die Beobachtungsfläche. Er gewährt keine Nachtnutzung von Küstenwegen, Leuchtturmaussicht oder Privatgrund. Halte Ausrüstung und Licht auf dem Campingplatz und befolge die Gästeregeln." } },
    ],
  });
}

function reviseRichtersveld(guide) {
  applyEditorialRevision(guide, {
    standfirst: {
      en: "Richtersveld observation belongs inside a booked protected-area camp, not at an invented desert pull-off. Current operator material documents Potjiespram and De Hoop as separate reservable campsites with facilities, gate times and layout information. Choose one camp for the whole night, arrive during permitted daylight access and use only the assigned camping footprint. A second camp requires another booking and daylight journey; the riverbank and surrounding desert are not fallback observing sites.",
      de: "Beobachtung im Richtersveld gehört auf einen gebuchten Schutzgebiets-Campingplatz und nicht an einen erfundenen Wüstenhalt. Aktuelles Betreibermaterial dokumentiert Potjiespram und De Hoop als getrennt reservierbare Camps mit Einrichtungen, Torzeiten und Lageplänen. Wähle ein Camp für die ganze Nacht, komme während erlaubter Tageszufahrt an und nutze nur die zugewiesene Campingfläche. Ein zweites Camp benötigt eine eigene Buchung und Tagesfahrt; Flussufer und umgebende Wüste sind keine Ersatzorte.",
    },
    editorialAngle: {
      en: "The overnight booking is the access evidence. Potjiespram at roughly 42 metres and De Hoop at roughly 81 metres are low river-corridor camps, not high desert viewpoints, and their operator instructions outrank any old staged elevation or map impression.",
      de: "Die Übernachtungsbuchung ist der Zugangsbeleg. Potjiespram auf ungefähr 42 Metern und De Hoop auf rund 81 Metern sind niedrig gelegene Camps im Flusskorridor und keine hohen Wüstenaussichten; Betreiberhinweise stehen über alten Höhenwerten oder Karteneindrücken.",
    },
    sections: {
      "richtersveld-where": {
        en: [
          "Potjiespram and De Hoop appear in current operator accommodation pages with their own facilities and camp layouts. Those records provide a reproducible visitor context but stop at the campsite boundary. A reservation assigns a legal overnight base; it does not establish public parking on a nearby road, free movement along the riverbank or permission to select a darker patch beyond the allocated site.",
          "The updated terrain checks place Potjiespram near 42 metres and De Hoop near 81 metres, replacing implausible staged values of 410 and 480 metres. Sendelingsdrift is about 37 metres in the same lookup. These figures clarify the low landscape but do not replace the catalogue's final DEM refresh or current protected-area instructions. Plan heat, wind and access for the actual camp rather than a fictional high plateau.",
        ],
        de: [
          "Potjiespram und De Hoop erscheinen auf aktuellen Betreiberseiten mit eigenen Einrichtungen und Camp-Lageplänen. Diese Einträge schaffen einen reproduzierbaren Besucherkontext, enden jedoch an der Campinggrenze. Eine Reservierung weist eine legale Übernachtungsbasis zu; sie belegt weder öffentliches Parken an einer nahen Straße noch freie Bewegung am Flussufer oder die Wahl einer dunkleren Fläche außerhalb des Stellplatzes.",
          "Die aktualisierten Geländekontrollen verorten Potjiespram bei ungefähr 42 Metern und De Hoop bei etwa 81 Metern und ersetzen unplausible alte Werte von 410 und 480 Metern. Sendelingsdrift liegt in derselben Abfrage bei rund 37 Metern. Diese Zahlen klären die Tieflage, ersetzen aber weder den endgültigen DEM-Lauf noch aktuelle Schutzgebietshinweise. Plane Hitze, Wind und Zugang für das wirkliche Camp statt für ein erfundenes Hochplateau.",
        ],
      },
      "richtersveld-conditions": {
        en: [
          "Gate hours, booking status, road access and protected-area rules determine whether either camp can be reached. Check the operator's current material before travel and carry the permits and reservation required for the chosen night. A historical catalogue entry cannot override a closure, changed gate time or route restriction, and silence about a riverbank is not permission to use it.",
          "Daylight arrival is part of the safety model because camp layout, road surface and assigned pitch must be understood before darkness. Once settled, keep the vehicle parked and judge wind, temperature and dust from the camp itself. If conditions deteriorate, remain within the booked footprint or shelter there. Do not drive to the other camp, a viewpoint or the river after dark.",
        ],
        de: [
          "Torzeiten, Buchungsstatus, Straßenzugang und Schutzgebietsregeln bestimmen, ob ein Camp erreichbar ist. Prüfe vor der Reise aktuelles Betreibermaterial und führe die für die gewählte Nacht nötige Reservierung und Genehmigung mit. Ein historischer Katalogeintrag überstimmt weder Sperrung noch geänderte Torzeit oder Routenbeschränkung; fehlende Angaben zum Flussufer sind keine Nutzungserlaubnis.",
          "Ankunft bei Tageslicht gehört zum Sicherheitsmodell, weil Campaufteilung, Straßenoberfläche und Stellplatz vor der Dunkelheit verständlich sein müssen. Danach bleibt das Fahrzeug stehen, und Wind, Temperatur sowie Staub werden am Camp beurteilt. Verschlechtert sich die Lage, bleibe innerhalb der Buchungsfläche oder suche dort Schutz. Fahre nachts weder zum anderen Camp noch zu Aussichtspunkt oder Fluss.",
        ],
      },
    },
    tour: {
      summary: { en: "Reserve either Potjiespram or De Hoop, enter within current gate hours and reach the assigned campsite before dark. Observe beside that pitch with the vehicle parked and every facility boundary respected. Sleep at the booked camp and depart in daylight. Do not transfer between camps, investigate the riverbank or add an unverified desert viewpoint after sunset.", de: "Reserviere entweder Potjiespram oder De Hoop, passiere das Tor innerhalb aktueller Zeiten und erreiche den zugewiesenen Stellplatz vor der Dunkelheit. Beobachte neben diesem Platz bei geparktem Fahrzeug und innerhalb aller Campgrenzen. Übernachte im gebuchten Camp und fahre bei Tageslicht ab. Wechsle nach Sonnenuntergang weder das Camp noch erkunde Flussufer oder ungeprüfte Wüstenaussicht." },
      suitability: { en: "Suitable for booked protected-area campers equipped for remote heat, dust and changing access who can remain inside one assigned footprint from daylight arrival until daylight departure.", de: "Geeignet für gebuchte Schutzgebietscamper mit Ausrüstung für abgelegene Hitze, Staub und wechselnden Zugang, die von Tagesankunft bis Tagesabfahrt auf einer zugewiesenen Fläche bleiben." },
      steps: {
        "richtersveld-check": { en: "Choose one campsite and verify its current reservation, gate hours, access route, facilities and protected-area requirements in the operator's published material. Save the camp layout and permits offline. Treat the 42- or 81-metre elevation only as planning context, not as proof that the road is open.", de: "Wähle ein Camp und prüfe aktuelle Reservierung, Torzeiten, Zufahrtsroute, Einrichtungen und Schutzgebietsanforderungen im veröffentlichten Betreibermaterial. Speichere Lageplan und Genehmigungen offline. Nutze 42 oder 81 Meter nur als Planungskontext und nicht als Beleg für eine offene Straße." },
        "richtersveld-arrive": { en: "Enter within the published gate window and complete the drive while camp roads and the assigned pitch remain visible. Park inside that footprint, identify facilities and shelter, and finish all vehicle movement before dark. If instructions or road conditions differ, follow the current operator rule rather than the prepared itinerary.", de: "Fahre innerhalb des veröffentlichten Torfensters ein und beende die Strecke, solange Campstraßen und zugewiesener Platz sichtbar sind. Parke innerhalb dieser Fläche, erkenne Einrichtungen und Schutz und schließe jede Fahrzeugbewegung vor Dunkelheit ab. Weichen Hinweise oder Straße ab, gilt die aktuelle Betreiberregel statt der vorbereiteten Route." },
        "richtersveld-observe": { en: "Set up only beside the booked pitch, shielding red light from neighbouring campers and wildlife. Keep roads, river access and facilities unobstructed and secure equipment against wind and dust. The surrounding desert may look empty, but the reservation covers the campsite rather than an expandable astronomy field.", de: "Baue ausschließlich neben dem gebuchten Stellplatz auf und schirme Rotlicht gegenüber Nachbarcampern und Wildtieren ab. Halte Straßen, Flusszugang und Einrichtungen frei und sichere Ausrüstung gegen Wind und Staub. Die umgebende Wüste wirkt leer, doch die Reservierung gilt für das Camp und nicht für ein erweiterbares Astronomiefeld." },
        "richtersveld-leave": { en: "Pack into the campsite and remain at the booked overnight base until a lawful daylight departure. Do not make a late transfer to De Hoop, Potjiespram, Sendelingsdrift or an unnamed river point. Check current gate timing again before beginning the return route.", de: "Verstaue alles im Camp und bleibe bis zur legalen Tagesabfahrt an der gebuchten Übernachtungsbasis. Wechsle spät weder nach De Hoop, Potjiespram oder Sendelingsdrift noch zu einem unbenannten Flusspunkt. Prüfe vor dem Rückweg erneut die aktuelle Torzeit." },
      },
    },
    fieldNotes: {
      "richtersveld-access-note": { en: "Operator pages support reservable camps with gate, facility and layout information. They do not establish separate public desert, roadside or riverbank observing sites, so the assigned pitch remains the complete night footprint.", de: "Betreiberseiten belegen reservierbare Camps mit Tor-, Einrichtungs- und Lageinformationen. Sie belegen keine getrennten öffentlichen Wüsten-, Straßenrand- oder Flussuferplätze; der zugewiesene Stellplatz bleibt die vollständige Nachtfläche." },
      "richtersveld-weather-note": { en: "The corrected low elevations change expectations for heat and exposure. Check current camp-specific wind, temperature, dust and road information, and remember that the figures remain subject to the catalogue's independent DEM confirmation.", de: "Die korrigierten niedrigen Höhen verändern die Erwartung an Hitze und Exposition. Prüfe aktuelle campbezogene Angaben zu Wind, Temperatur, Staub und Straße; die Höhen bleiben bis zur unabhängigen DEM-Bestätigung des Katalogs vorläufig." },
      "richtersveld-light-note": { en: "A booked camp is shared accommodation inside a protected landscape. Prepare screens before sunset, use brief shielded red light and avoid vehicle movement or beams toward neighbouring pitches, river habitat and camp roads.", de: "Ein gebuchtes Camp ist gemeinsam genutzte Unterkunft in geschützter Landschaft. Bereite Displays vor Sonnenuntergang vor, nutze kurzes abgeschirmtes Rotlicht und vermeide Fahrzeugbewegung oder Licht zu Nachbarplätzen, Flusshabitat und Campstraßen." },
    },
    faq: [
      { question: { en: "Can observers leave the Richtersveld campsite after dark?", de: "Können Beobachter das Richtersveld-Camp nachts verlassen?" }, answer: { en: "The reviewed sources support an overnight booking inside Potjiespram or De Hoop, not a separate night drive or riverbank site. Remain in the assigned footprint and follow current park instructions. A second camp or viewpoint requires its own booking and a separately planned daylight journey.", de: "Die geprüften Quellen stützen eine Übernachtungsbuchung in Potjiespram oder De Hoop und keine getrennte Nachtfahrt oder Flussuferstelle. Bleibe auf der zugewiesenen Fläche und folge aktuellen Parkhinweisen. Ein zweites Camp oder ein Aussichtspunkt verlangt eigene Buchung und getrennt geplante Tagesfahrt." } },
      { question: { en: "Why are the camp elevations lower than earlier values?", de: "Warum liegen die Camp-Höhen niedriger als frühere Werte?" }, answer: { en: "A reviewed elevation lookup returned about 42 metres for Potjiespram and 81 metres for De Hoop, replacing implausible staged values of 410 and 480 metres. They describe a low river corridor and remain pending independent confirmation by the combined catalogue DEM ingestion.", de: "Eine geprüfte Höhenabfrage ergab ungefähr 42 Meter für Potjiespram und 81 Meter für De Hoop und ersetzt unplausible alte Werte von 410 und 480 Metern. Sie beschreiben einen niedrigen Flusskorridor und warten noch auf unabhängige Bestätigung durch den kombinierten DEM-Kataloglauf." } },
    ],
  });
}

function reviseKangarooIsland(guide) {
  applyEditorialRevision(guide, {
    standfirst: {
      en: "Flinders Chase is officially promoted for stargazing, but the workable night begins with one campsite reservation. Rocky River offers allocated sites and visitor facilities; West Bay is a separate remote campground whose road requires four-wheel drive and may close after rain. Arrive in daylight, observe beside the assigned pitch and keep the vehicle parked until morning. Attractions, coast roads and the other campground are not after-dark extensions of the booking.",
      de: "Flinders Chase wird offiziell für Sternbeobachtung beworben, doch eine praktikable Nacht beginnt mit genau einer Campingreservierung. Rocky River bietet zugewiesene Stellplätze und Besuchereinrichtungen; West Bay ist ein getrenntes abgelegenes Camp, dessen Straße Allrad verlangt und nach Regen schließen kann. Komme bei Tageslicht an, beobachte neben dem Stellplatz und lasse das Fahrzeug bis zum Morgen stehen. Sehenswürdigkeiten, Küstenstraßen und das andere Camp sind keine nächtliche Erweiterung der Buchung.",
    },
    editorialAngle: { en: "Rocky River is the primary low-complexity base; West Bay suits a separately prepared four-wheel-drive stay. Official georeferenced campground footprints define both locations more reliably than attraction pins or open-looking park roads.", de: "Rocky River ist die weniger komplexe Hauptbasis; West Bay eignet sich für einen getrennt vorbereiteten Allradaufenthalt. Offizielle georeferenzierte Campflächen definieren beide Orte verlässlicher als Sehenswürdigkeitspunkte oder offen wirkende Parkstraßen." },
    sections: {
      "kangaroo-island-where": {
        en: ["Parks SA identifies Rocky River and West Bay as distinct bookable campgrounds within Flinders Chase. The catalogue points sit inside their official georeferenced campground footprints, so they represent visitor accommodation rather than vague park-area pins. At Rocky River, allocated sites and established facilities make the assigned pitch the clear place for a quiet observing setup after other camp tasks are complete.", "West Bay has a different access burden: the official information requires four-wheel drive and warns that the road may close after rain. Its remoteness is not a reason to add it after Rocky River or a park attraction. A booking, daylight road check and assigned site must all agree before travel; otherwise use another date rather than attempting the track."],
        de: ["Parks SA führt Rocky River und West Bay als getrennte buchbare Campingplätze in Flinders Chase. Die Katalogpunkte liegen innerhalb ihrer offiziellen georeferenzierten Campflächen und repräsentieren Besucherunterkünfte statt vager Parkpunkte. In Rocky River machen zugewiesene Stellplätze und bestehende Einrichtungen den eigenen Platz zur klaren Fläche für einen ruhigen Aufbau nach Abschluss anderer Camparbeiten.", "West Bay besitzt eine andere Zugangshürde: Die offizielle Information verlangt Allrad und warnt vor möglicher Straßensperrung nach Regen. Die Abgelegenheit ist kein Grund, das Camp nach Rocky River oder einer Sehenswürdigkeit anzufahren. Buchung, Tageslichtprüfung der Straße und zugewiesener Platz müssen vor der Fahrt zusammenpassen; andernfalls gilt ein anderer Termin statt Streckenversuch."],
      },
      "kangaroo-island-conditions": {
        en: ["Check Flinders Chase opening information, fire and weather conditions, then verify the exact campground booking. For West Bay, recent rain can remove the road from the plan even when the sky forecast is clear. Rocky River's facilities reduce logistical uncertainty but do not eliminate wildlife, wind or park restrictions. The live decision belongs to the chosen camp, not Kangaroo Island as a whole.", "Complete every transfer in daylight. Park roads connect wildlife habitat and visitor attractions rather than astronomy stations, and night driving adds collision and navigation risk. If clouds or wind spoil observing, stay at the booked site. Do not drive from campground to campground or attraction to attraction looking for a clearer patch."],
        de: ["Prüfe Öffnungsinformationen, Feuer- und Wetterlage für Flinders Chase und bestätige anschließend die konkrete Campingbuchung. Für West Bay kann jüngster Regen die Straße aus dem Plan nehmen, obwohl der Himmel klar prognostiziert ist. Einrichtungen in Rocky River reduzieren Logistik, beseitigen aber weder Wildtiere noch Wind oder Parkregeln. Die Live-Entscheidung gilt für das gewählte Camp und nicht Kangaroo Island insgesamt.", "Beende jeden Transfer bei Tageslicht. Parkstraßen verbinden Wildtierhabitat und Besucherattraktionen statt Astronomiestationen; Nachtfahrten erhöhen Kollisions- und Navigationsrisiko. Verhindern Wolken oder Wind die Beobachtung, bleibe am gebuchten Platz. Fahre nicht zwischen Camps oder Sehenswürdigkeiten umher, um eine klarere Stelle zu suchen."],
      },
    },
    tour: {
      summary: { en: "Book Rocky River for the primary plan or reserve West Bay for a separate four-wheel-drive trip. Reach the allocated pitch before dark, complete all vehicle movement, and observe only from the campsite footprint. Remain there overnight and leave in daylight. A failed sky session never becomes permission to drive toward the coast, an attraction or the second campground.", de: "Buche Rocky River für den Hauptplan oder reserviere West Bay für eine getrennte Allradfahrt. Erreiche den zugewiesenen Stellplatz vor der Dunkelheit, beende jede Fahrzeugbewegung und beobachte nur von der Campfläche. Bleibe dort über Nacht und fahre bei Tageslicht ab. Eine gescheiterte Himmelsbeobachtung erlaubt keine Fahrt zu Küste, Sehenswürdigkeit oder zweitem Camp." },
      suitability: { en: "Suitable for booked campers who can arrive and depart in daylight, keep a wildlife-aware stationary night and match vehicle capability to the chosen campground, especially West Bay's four-wheel-drive road.", de: "Geeignet für gebuchte Camper mit Tagesankunft und -abfahrt, einer stationären wildtierbewussten Nacht und zum gewählten Camp passendem Fahrzeug, besonders für die Allradstraße nach West Bay." },
      steps: {
        "kangaroo-island-check": { en: "Confirm one campground booking, current park opening and fire or weather conditions. For West Bay, verify that the road is open after recent rain and that the vehicle meets the four-wheel-drive requirement. Save the official campground map instead of navigating to an attraction or broad park coordinate.", de: "Bestätige eine Campingbuchung sowie aktuelle Parköffnung, Feuer- und Wetterlage. Prüfe für West Bay nach jüngstem Regen die offene Straße und die Allradeignung des Fahrzeugs. Speichere den offiziellen Campplan statt zu einer Sehenswürdigkeit oder allgemeinen Parkkoordinate zu navigieren." },
        "kangaroo-island-arrive": { en: "Drive to the assigned Rocky River or West Bay site while roads, wildlife and camp layout remain visible. Park as shown, identify facilities and finish any unloading before dusk. If the road, booking or site allocation differs from the plan, follow Parks SA instructions and do not improvise elsewhere.", de: "Fahre zum zugewiesenen Platz in Rocky River oder West Bay, solange Straßen, Wildtiere und Campaufteilung sichtbar sind. Parke wie vorgesehen, erkenne Einrichtungen und beende das Ausladen vor der Dämmerung. Weichen Straße, Buchung oder Zuweisung ab, folge Parks-SA-Hinweisen und improvisiere nicht anderswo." },
        "kangaroo-island-observe": { en: "Set up beside the pitch without blocking camp roads or neighbouring sites. Use low shielded red light, minimise noise and remain alert to wildlife moving through the campground. The official stargazing promotion supports the activity at Flinders Chase, while the reservation defines where this particular night occurs.", de: "Baue neben dem Stellplatz auf, ohne Campstraßen oder Nachbarplätze zu blockieren. Nutze schwaches abgeschirmtes Rotlicht, vermeide Lärm und achte auf Wildtiere im Camp. Die offizielle Stargazing-Bewerbung stützt die Aktivität in Flinders Chase; die Reservierung bestimmt den Ort dieser Nacht." },
        "kangaroo-island-leave": { en: "Pack into the campsite and remain there until daylight. Do not use the end of observing for a drive to West Bay, Rocky River or a park attraction. Recheck road and weather information before departing, particularly after rain on the West Bay route.", de: "Verstaue alles am Campingplatz und bleibe bis zum Tageslicht. Nutze das Beobachtungsende nicht für eine Fahrt nach West Bay, Rocky River oder zu einer Parkattraktion. Prüfe vor der Abfahrt erneut Straße und Wetter, besonders nach Regen auf der West-Bay-Route." },
      },
    },
    fieldNotes: {
      "kangaroo-island-access-note": { en: "Parks SA supports stargazing in Flinders Chase and separately documents both bookable campgrounds. That evidence anchors observation to an allocated campsite; it does not turn attraction parking, coast roads or the other camp into night-access overflow.", de: "Parks SA unterstützt Sternbeobachtung in Flinders Chase und dokumentiert beide buchbaren Camps getrennt. Das verankert Beobachtung am zugewiesenen Stellplatz und macht weder Attraktionsparkplätze noch Küstenstraßen oder das andere Camp zur Nacht-Ausweichfläche." },
      "kangaroo-island-weather-note": { en: "West Bay's road may close after rain and requires four-wheel drive, so surface access can veto a clear forecast. Rocky River has different facilities and access. Judge the exact booked camp before entering the park.", de: "Die West-Bay-Straße kann nach Regen schließen und verlangt Allrad; der Untergrund kann also eine klare Prognose überstimmen. Rocky River besitzt andere Einrichtungen und Zufahrt. Beurteile das genau gebuchte Camp vor Parkeinfahrt." },
      "kangaroo-island-light-note": { en: "Campgrounds are shared wildlife settings. Prepare vehicle lights before dusk, direct red light at the ground and avoid beams across roads, vegetation and adjacent pitches once the stationary night begins.", de: "Campingplätze sind gemeinsam genutzte Wildtierumgebungen. Bereite Fahrzeuglicht vor der Dämmerung vor, richte Rotlicht zum Boden und vermeide nach Beginn der stationären Nacht Strahlen über Straßen, Vegetation und Nachbarplätze." },
    },
    faq: [
      { question: { en: "Should visitors choose Rocky River or West Bay?", de: "Sollten Besucher Rocky River oder West Bay wählen?" }, answer: { en: "Rocky River offers allocated sites and established visitor facilities, making it the simpler primary base. West Bay is a separate remote booking whose road requires four-wheel drive and may close after rain. Choose before travel and spend the full night at that one campground.", de: "Rocky River bietet zugewiesene Plätze und bestehende Besuchereinrichtungen und ist damit die einfachere Hauptbasis. West Bay ist eine getrennte abgelegene Buchung; die Straße verlangt Allrad und kann nach Regen schließen. Wähle vor der Reise und verbringe die ganze Nacht in genau diesem Camp." } },
      { question: { en: "Can stargazers drive between Flinders Chase sites after dark?", de: "Können Sternbeobachter nachts zwischen Orten in Flinders Chase fahren?" }, answer: { en: "This guide does not recommend it. The verified plan is daylight arrival at one booked campground, observation beside the assigned pitch and daylight departure. Staying parked reduces wildlife and navigation risk, while a booking at one camp grants no site at another campground or attraction.", de: "Dieser Guide empfiehlt es nicht. Der belegte Plan besteht aus Tagesankunft an einem gebuchten Camp, Beobachtung neben dem zugewiesenen Platz und Tagesabfahrt. Stehenbleiben senkt Wildtier- und Navigationsrisiko; eine Buchung in einem Camp gewährt keinen Platz an einem anderen oder einer Sehenswürdigkeit." } },
    ],
  });
}

function reviseMudgee(guide) {
  applyEditorialRevision(guide, {
    standfirst: {
      en: "Mudgee offers two source-backed but incompatible night formats. Mudgee Observatory at 961 Old Grattai Road runs seasonal public day and night sessions only by essential advance booking. Grattai Grove is separate private accommodation whose official listing promotes Milky Way viewing by overnight guests. Select one confirmed programme or one booked property for the entire night; neither reservation permits a roadside, paddock or cross-property fallback.",
      de: "Mudgee bietet zwei quellenbelegte, aber nicht kombinierbare Nachtformate. Das Mudgee Observatory an der 961 Old Grattai Road führt saisonale öffentliche Tages- und Nachtsitzungen nur mit zwingender Vorabbuchung durch. Grattai Grove ist eine getrennte Privatunterkunft, deren offizieller Eintrag Milchstraßenbeobachtung für Übernachtungsgäste bewirbt. Wähle ein bestätigtes Programm oder ein gebuchtes Grundstück für die ganze Nacht; keine Reservierung erlaubt Straßenrand, Weide oder Wechsel zum anderen Grundstück.",
    },
    editorialAngle: { en: "The observatory booking supplies session time and exact facility access; the Grattai Grove booking supplies an accommodation footprint and night-driving directions. The former unsupported Gulgong pin has no role in either plan.", de: "Die Observatoriumsbuchung liefert Sitzungszeit und genauen Anlagenzugang; die Grattai-Grove-Buchung liefert Unterkunftsfläche und Hinweise zur Nachtanreise. Der frühere unbelegte Gulgong-Punkt spielt in keinem Plan eine Rolle." },
    sections: {
      "mudgee-where": {
        en: ["Mudgee Observatory is an exact visitor facility rather than a regional marker. Tourism and operator sources place it at 961 Old Grattai Road, publish its location and make advance booking essential. Seasonal session times arrive with the reservation, so that confirmation defines both arrival and observation. The mapped observatory feature does not support independent use of the entrance or surrounding rural road outside a session.", "Grattai Grove's destination listing publishes the property coordinate and explicitly describes Milky Way stargazing after nightfall. The operator offers two accommodation choices, onsite parking directions and warnings about wildlife during twilight and night approaches. Those facts support observing as an overnight guest on the assigned property footprint, not entering a paddock or arriving without accommodation."],
        de: ["Das Mudgee Observatory ist eine genaue Besuchereinrichtung statt eines Regionalpunkts. Tourismus- und Betreiberquellen verorten es an der 961 Old Grattai Road, veröffentlichen die Lage und verlangen zwingende Vorabbuchung. Saisonale Sitzungszeiten kommen mit der Reservierung; diese Bestätigung definiert Ankunft und Beobachtung. Das kartierte Observatorium belegt keine selbstständige Nutzung von Eingang oder ländlicher Straße außerhalb eines Termins.", "Der Destinationseintrag von Grattai Grove veröffentlicht die Grundstückskoordinate und beschreibt ausdrücklich Milchstraßenbeobachtung nach Einbruch der Dunkelheit. Der Betreiber bietet zwei Unterkunftsformen, Parkhinweise vor Ort und Warnungen vor Wildtieren bei Dämmerungs- und Nachtanreise. Das stützt Beobachtung als Übernachtungsgast auf der zugewiesenen Grundstücksfläche und weder Weidezutritt noch Ankunft ohne Unterkunft."],
      },
      "mudgee-conditions": {
        en: ["For the observatory, the booked seasonal time and operator's programme determine whether a night session exists. Check weather against that slot and accept any change rather than arriving independently. For Grattai Grove, combine the accommodation instructions with a daylight arrival whenever possible; wildlife risk on twilight and night approaches makes a late cross-property transfer particularly unsuitable.", "Cloud or a cancelled session does not connect the two venues. The observatory booking grants no access to Grattai Grove, and an accommodation stay grants no observatory entry. If the chosen format fails, remain at lawful accommodation or return by the known route. Do not restore the unsupported Gulgong location or stop at an apparently open roadside or paddock."],
        de: ["Beim Observatorium bestimmen gebuchte Saisonzeit und Betreiberprogramm, ob eine Nachtsitzung stattfindet. Prüfe das Wetter gegen dieses Zeitfenster und akzeptiere Änderungen, statt selbstständig anzureisen. Bei Grattai Grove verbindest du Unterkunftshinweise möglichst mit Tagesankunft; das Wildtierrisiko bei Dämmerungs- und Nachtfahrt macht einen späten Grundstückswechsel besonders ungeeignet.", "Wolken oder eine abgesagte Sitzung verbinden die Orte nicht. Die Observatoriumsbuchung gewährt keinen Zugang zu Grattai Grove, und eine Unterkunft gewährt keinen Observatoriumseintritt. Scheitert das gewählte Format, bleibe in legaler Unterkunft oder kehre auf der bekannten Route zurück. Reaktiviere weder den unbelegten Gulgong-Ort noch halte an offen wirkendem Straßenrand oder Weide."],
      },
    },
    tour: {
      summary: { en: "For the primary plan, book a seasonal Mudgee Observatory night session and follow the supplied time and arrival instructions at 961 Old Grattai Road. Participate only within that programme and return directly afterward. Use Grattai Grove on a different night as a booked accommodation stay, with onsite parking and observation kept inside the assigned property footprint.", de: "Buche für den Hauptplan eine saisonale Nachtsitzung im Mudgee Observatory und folge Zeit- und Anreiseangaben für 961 Old Grattai Road. Nimm nur innerhalb dieses Programms teil und kehre danach direkt zurück. Nutze Grattai Grove in einer anderen Nacht als gebuchte Unterkunft mit Parkplatz vor Ort und Beobachtung innerhalb der zugewiesenen Grundstücksfläche." },
      suitability: { en: "Suitable for advance-booked observatory participants or registered accommodation guests who can follow one venue's exact timing and wildlife-aware arrival without adding a rural-road or paddock stop.", de: "Geeignet für vorab gebuchte Observatoriumsteilnehmer oder registrierte Unterkunftsgäste, die Zeitplan und wildtierbewusste Anreise eines Ortes befolgen, ohne Straßenrand- oder Weidestopp hinzuzufügen." },
      steps: {
        "mudgee-check": { en: "Confirm either the observatory's seasonal session time or one of Grattai Grove's accommodation options. Save the exact property directions and weather information. A regional Mudgee forecast, map pin or old Gulgong record cannot replace the reservation required by the chosen venue.", de: "Bestätige entweder die saisonale Observatoriumszeit oder eine Unterkunftsoption von Grattai Grove. Speichere genaue Grundstücksanfahrt und Wetterinformation. Eine regionale Mudgee-Prognose, Kartenmarke oder der alte Gulgong-Eintrag ersetzt nicht die nötige Reservierung des gewählten Ortes." },
        "mudgee-arrive": { en: "Reach 961 Old Grattai Road at the supplied programme time or arrive at Grattai Grove under its parking directions, preferably before wildlife becomes harder to see. Check in before unloading. Do not continue past an entrance or onto an adjacent paddock when the booking instructions differ from expectation.", de: "Erreiche 961 Old Grattai Road zur mitgeteilten Programmzeit oder Grattai Grove nach dessen Parkhinweisen, möglichst bevor Wildtiere schwerer sichtbar werden. Melde dich vor dem Ausladen an. Fahre bei Abweichungen weder am Eingang vorbei noch auf eine Nachbarweide." },
        "mudgee-observe": { en: "At the observatory, remain with the public session and follow staff around instruments and lighting. At Grattai Grove, keep equipment beside the assigned accommodation and protect other guests' darkness. The Milky Way promotion supports booked guest use, not an expandable private-property observing field.", de: "Bleibe am Observatorium bei der öffentlichen Sitzung und folge Personalhinweisen zu Instrumenten und Licht. Halte auf Grattai Grove Ausrüstung an der zugewiesenen Unterkunft und schütze die Dunkelheit anderer Gäste. Die Milchstraßenwerbung stützt gebuchte Gästenutzung und kein erweiterbares Privatgrund-Beobachtungsfeld." },
        "mudgee-leave": { en: "Leave the observatory when its session ends or remain overnight within the Grattai Grove booking. Do not travel from one venue to the other after dark. Follow the known road carefully for wildlife and finish without testing an unverified roadside, Gulgong point or field entrance.", de: "Verlasse das Observatorium zum Sitzungsende oder bleibe innerhalb der Grattai-Grove-Buchung über Nacht. Fahre nachts nicht von einem Ort zum anderen. Folge der bekannten Straße wildtierbewusst und beende den Abend ohne ungeprüften Straßenrand, Gulgong-Punkt oder Feldeinfahrt." },
      },
    },
    fieldNotes: {
      "mudgee-access-note": { en: "The observatory requires essential advance booking, while Grattai Grove requires an accommodation reservation. Exact coordinates resolve each visitor facility but do not create walk-in access, cross-property permission or a rural-road fallback.", de: "Das Observatorium verlangt zwingende Vorabbuchung, Grattai Grove eine Unterkunftsreservierung. Genaue Koordinaten klären beide Besuchereinrichtungen, schaffen aber weder spontanen Zutritt noch Grundstückswechsel oder ländlichen Straßenersatz." },
      "mudgee-weather-note": { en: "Match weather to the observatory's supplied seasonal time or the accommodation night. If the programme changes, follow that outcome. A clear patch elsewhere does not justify additional night driving where the operator already warns about wildlife.", de: "Gleiche Wetter mit der mitgeteilten saisonalen Observatoriumszeit oder Unterkunftsnacht ab. Ändert sich das Programm, gilt dieses Ergebnis. Eine klare Stelle anderswo rechtfertigt keine zusätzliche Nachtfahrt bei ausdrücklich genanntem Wildtierrisiko." },
      "mudgee-light-note": { en: "Both venues are managed visitor properties. Prepare screens before arrival, follow staff light rules at the observatory and use brief shielded red light beside the accommodation without illuminating access roads or neighbouring guest areas.", de: "Beide Orte sind verwaltete Besuchergrundstücke. Bereite Displays vor der Ankunft vor, folge am Observatorium den Lichtregeln und nutze an der Unterkunft kurzes abgeschirmtes Rotlicht ohne Zufahrten oder Nachbargästebereiche zu beleuchten." },
    },
    faq: [
      { question: { en: "Can visitors arrive at Mudgee Observatory without booking?", de: "Können Besucher ohne Buchung am Mudgee Observatory ankommen?" }, answer: { en: "No. The tourism and operator sources make advance booking essential for public day and night sessions, with seasonal times supplied through that process. Use the exact facility only for a confirmed programme and do not treat its road, entrance or coordinate as an independent observing stop.", de: "Nein. Tourismus- und Betreiberquellen machen Vorabbuchung für öffentliche Tages- und Nachtsitzungen zwingend; saisonale Zeiten werden dabei mitgeteilt. Nutze die genaue Anlage nur für ein bestätigtes Programm und behandle Straße, Eingang oder Koordinate nicht als selbstständigen Beobachtungshalt." } },
      { question: { en: "What does a Grattai Grove booking support?", de: "Was ermöglicht eine Grattai-Grove-Buchung?" }, answer: { en: "Its official listing promotes Milky Way viewing after nightfall, and the operator provides two accommodation options plus onsite parking directions. That supports stargazing as an overnight guest within the assigned property area. It does not include the observatory, nearby paddocks or the removed Gulgong location.", de: "Der offizielle Eintrag bewirbt Milchstraßenbeobachtung nach Einbruch der Dunkelheit; der Betreiber bietet zwei Unterkunftsoptionen und Parkhinweise vor Ort. Das stützt Sternbeobachtung als Übernachtungsgast innerhalb der zugewiesenen Grundstücksfläche. Observatorium, Nachbarweiden und entfernter Gulgong-Ort sind nicht enthalten." } },
    ],
  });
}

function reviseFundy(guide) {
  applyEditorialRevision(guide, {
    standfirst: {
      en: "Parks Canada links Fundy stargazing to a practical overnight base: Chignecto Campground is recommended near the activity, while Wolfe Lake is documented as a secluded viewing place. Book and verify Chignecto first, arrive there in daylight and treat Wolfe Lake as one separately checked excursion with a return to the same camp. Neither park-wide darkness nor a visitor coordinate overrides seasonal openings, current road conditions or an established surface.",
      de: "Parks Canada verbindet Sternbeobachtung in Fundy mit einer praktischen Übernachtungsbasis: Chignecto Campground wird nahe der Aktivität empfohlen, während Wolfe Lake als abgeschiedener Beobachtungsort dokumentiert ist. Buche und prüfe zuerst Chignecto, komme dort bei Tageslicht an und behandle Wolfe Lake als einen getrennt kontrollierten Ausflug mit Rückkehr ins gleiche Camp. Weder parkweite Dunkelheit noch Besucherkoordinate überstimmt Saisonöffnung, aktuelle Straßenlage oder bestehende Besucherfläche.",
    },
    editorialAngle: { en: "Chignecto supplies the booked bed and decision point; Wolfe Lake supplies the optional named viewing setting. The route succeeds only when both the outward road and the same-night return are confirmed before departure.", de: "Chignecto liefert gebuchte Übernachtung und Entscheidungspunkt; Wolfe Lake die optionale benannte Beobachtungsumgebung. Die Route gelingt nur, wenn Hinweg und Rückkehr in derselben Nacht vor Abfahrt bestätigt sind." },
    sections: {
      "fundy-where": {
        en: ["Parks Canada publishes the Chignecto Campground coordinate and recommends the campground as a base close to stargazing activity. That makes a booked pitch the stable start and finish of the evening. Settle there first, learn the campground layout and keep ordinary camp access clear. The reservation supports overnight use at Chignecto rather than an unspecified park clearing.", "Wolfe Lake has its own published visitor coordinate and is described as a secluded viewing place. It remains a visit from the camp, not a second accommodation base. Use the established visitor surface and only when current opening and road information supports both directions. A quiet-looking roadside between the two points is not an equivalent substitute."],
        de: ["Parks Canada veröffentlicht die Koordinate des Chignecto Campground und empfiehlt ihn als Basis nahe der Stargazing-Aktivität. Ein gebuchter Stellplatz wird damit zum stabilen Start und Ende des Abends. Richte dich zuerst dort ein, lerne die Campaufteilung und halte normale Zugänge frei. Die Reservierung stützt die Übernachtung in Chignecto statt einer unbestimmten Parklichtung.", "Wolfe Lake besitzt eine eigene veröffentlichte Besucherkoordinate und wird als abgeschiedener Beobachtungsort beschrieben. Er bleibt ein Besuch vom Camp und keine zweite Unterkunftsbasis. Nutze die bestehende Besucherfläche nur, wenn aktuelle Öffnungs- und Straßeninformationen beide Richtungen tragen. Ein still wirkender Straßenrand zwischen den Punkten ist kein gleichwertiger Ersatz."],
      },
      "fundy-conditions": {
        en: ["Fundy's operating seasons, current closures and road conditions decide whether the prepared route exists. Verify Chignecto's booking and opening first, then check Wolfe Lake and the return road on the chosen date. Fog, rain or a closure at the lake should cancel the excursion without affecting the lawful camp stay; a historical score cannot reopen a park road.", "Daylight arrival at Chignecto provides time to organise equipment and judge whether leaving the base is still sensible. If the Wolfe Lake visit proceeds, set a return threshold before departure and use the same known road. If conditions change, remain at the booked camp. Do not turn a cancelled outing into a search along park roads after dark."],
        de: ["Betriebssaison, aktuelle Sperrungen und Straßenlage in Fundy entscheiden, ob die vorbereitete Route existiert. Bestätige zuerst Buchung und Öffnung von Chignecto und prüfe danach Wolfe Lake samt Rückstraße für das Datum. Nebel, Regen oder Sperrung am See sollen den Ausflug beenden, ohne den legalen Campaufenthalt zu verändern; ein historischer Wert öffnet keine Parkstraße.", "Die Ankunft in Chignecto bei Tageslicht schafft Zeit für Ausrüstung und die Entscheidung, ob das Verlassen der Basis sinnvoll bleibt. Findet der Wolfe-Lake-Besuch statt, lege vor Abfahrt eine Rückkehrgrenze fest und nutze dieselbe bekannte Straße. Ändert sich die Lage, bleibe im gebuchten Camp. Mache aus einem abgesagten Ausflug keine nächtliche Suche entlang von Parkstraßen."],
      },
    },
    tour: {
      summary: { en: "Book Chignecto Campground and establish the pitch before dark. If Wolfe Lake is currently open, its road and same-night return are suitable, make one visit to the named visitor surface and then return directly to Chignecto. Otherwise observe quietly from the lawful campground setting. The plan never requires a roadside stop or a second overnight base.", de: "Buche Chignecto Campground und richte den Stellplatz vor der Dunkelheit ein. Sind Wolfe Lake, Straße und Rückkehr in derselben Nacht aktuell geeignet, besuche einmal die benannte Besucherfläche und kehre direkt nach Chignecto zurück. Andernfalls beobachte ruhig in der legalen Campingumgebung. Der Plan benötigt weder Straßenrandhalt noch zweite Übernachtungsbasis." },
      suitability: { en: "Suitable for booked campers who can verify seasonal park operation, make a conservative same-night road decision and return to Chignecto without adding unlisted shore, trail or roadside locations.", de: "Geeignet für gebuchte Camper, die den saisonalen Parkbetrieb prüfen, eine vorsichtige Straßenentscheidung für dieselbe Nacht treffen und ohne ungenannte Ufer-, Weg- oder Straßenorte nach Chignecto zurückkehren." },
      steps: {
        "fundy-check": { en: "Confirm the Chignecto reservation, campground season and current park conditions. Check Wolfe Lake's opening and the full return road separately. Save both official coordinates and set a cancellation threshold; a lake visit is optional, while lawful overnight accommodation at the booked camp is essential.", de: "Bestätige Chignecto-Reservierung, Camp-Saison und aktuelle Parklage. Prüfe Öffnung von Wolfe Lake und vollständige Rückstraße getrennt. Speichere beide offiziellen Koordinaten und setze eine Abbruchgrenze; der Seebesuch ist optional, die legale Übernachtung im gebuchten Camp wesentlich." },
        "fundy-arrive": { en: "Reach Chignecto in daylight, check in and identify the assigned pitch, facilities and return point. Pack only the equipment needed for a possible Wolfe Lake visit. Do not leave until the road and timing still permit a calm return to the already established campsite.", de: "Erreiche Chignecto bei Tageslicht, melde dich an und erkenne Stellplatz, Einrichtungen und Rückkehrpunkt. Packe nur die für einen möglichen Wolfe-Lake-Besuch nötige Ausrüstung. Fahre erst ab, wenn Straße und Zeit weiterhin eine ruhige Rückkehr zum bereits eingerichteten Camp erlauben." },
        "fundy-observe": { en: "At Wolfe Lake, remain on the established visitor surface, minimise light and keep access open. At Chignecto, work beside the assigned pitch without disturbing other campers. Parks Canada's recommendation supports these named contexts, not movement onto an unlisted shore or trail for a wider horizon.", de: "Bleibe am Wolfe Lake auf der bestehenden Besucherfläche, minimiere Licht und halte den Zugang frei. Arbeite in Chignecto neben dem zugewiesenen Stellplatz ohne andere Camper zu stören. Die Empfehlung von Parks Canada stützt diese benannten Kontexte und nicht den Wechsel auf ungenanntes Ufer oder Weg für weiteren Horizont." },
        "fundy-leave": { en: "Leave Wolfe Lake at the predetermined time and retrace the checked road to Chignecto. If the outing never starts, keep the vehicle at camp. Finish by accounting for all equipment at the booked pitch; do not extend the night to another Fundy viewpoint or roadside opening.", de: "Verlasse Wolfe Lake zur vorher festgelegten Zeit und fahre auf der geprüften Straße nach Chignecto zurück. Beginnt der Ausflug nicht, bleibt das Fahrzeug am Camp. Beende den Abend mit vollständiger Ausrüstung am gebuchten Platz und erweitere ihn nicht um einen weiteren Aussichtspunkt oder Straßenrand." },
      },
    },
    fieldNotes: {
      "fundy-access-note": { en: "Parks Canada publishes named visitor coordinates for Chignecto and Wolfe Lake. Use them with the campground reservation, seasonal opening and current conditions; they do not authorise camping at the lake or stopping elsewhere in the park.", de: "Parks Canada veröffentlicht benannte Besucherkoordinaten für Chignecto und Wolfe Lake. Nutze sie mit Campingreservierung, Saisonöffnung und aktueller Lage; sie erlauben weder Camping am See noch Halte anderswo im Park." },
      "fundy-weather-note": { en: "Coastal fog, rain and road conditions can remove the Wolfe Lake excursion while leaving the Chignecto stay usable. Treat the lake as optional and the booked camp as shelter; never let a favourable historical score override a current closure.", de: "Küstennebel, Regen und Straßenlage können den Wolfe-Lake-Ausflug verhindern, während Chignecto nutzbar bleibt. Behandle den See als optional und das gebuchte Camp als Schutz; ein günstiger historischer Wert überstimmt keine aktuelle Sperrung." },
      "fundy-light-note": { en: "Wolfe Lake is valued for seclusion and Chignecto is shared camping space. Prepare screens at camp, use brief downward red light and avoid vehicle beams across the visitor surface, water or neighbouring pitches.", de: "Wolfe Lake wird wegen seiner Abgeschiedenheit geschätzt, Chignecto ist geteilter Campingraum. Bereite Displays am Camp vor, nutze kurzes Rotlicht nach unten und vermeide Fahrzeuglicht über Besucherfläche, Wasser oder Nachbarplätze." },
    },
    faq: [
      { question: { en: "Is Wolfe Lake an overnight camping alternative to Chignecto?", de: "Ist Wolfe Lake eine Übernachtungsalternative zu Chignecto?" }, answer: { en: "No. Parks Canada recommends Chignecto as the nearby campground base and describes Wolfe Lake as a secluded viewing place. Keep the accommodation booking at Chignecto and make only a separately checked visit when opening, road and return conditions allow it.", de: "Nein. Parks Canada empfiehlt Chignecto als nahe Campingbasis und beschreibt Wolfe Lake als abgeschiedenen Beobachtungsort. Behalte die Unterkunftsbuchung in Chignecto und mache nur einen getrennt geprüften Besuch, wenn Öffnung, Straße und Rückkehr es erlauben." } },
      { question: { en: "What happens if Wolfe Lake is closed or foggy?", de: "Was passiert, wenn Wolfe Lake geschlossen oder neblig ist?" }, answer: { en: "Cancel the excursion and remain at the booked campground. A closure or poor visibility does not justify searching other roads, shores or trails. Chignecto is the planned overnight base, so the night can end safely there even when the optional viewing trip produces no observation.", de: "Sage den Ausflug ab und bleibe im gebuchten Camp. Sperrung oder schlechte Sicht rechtfertigen keine Suche auf anderen Straßen, Ufern oder Wegen. Chignecto ist die geplante Übernachtungsbasis; dort kann die Nacht sicher enden, auch wenn der optionale Beobachtungsausflug ausfällt." } },
    ],
  });
}

function reviseEnchantedRock(guide) {
  applyEditorialRevision(guide, {
    standfirst: { en: "Enchanted Rock requires a choice between day-use access and an overnight camping reservation. Texas State Parks publishes timed entry windows and a separate inventory of walk-in tent sites; those footprints do not combine into a night route. Use the Loop Trail south trailhead area only while current day-use access and trails remain open, or observe from a booked campsite. The summit is not a fallback after trails close.", de: "Enchanted Rock verlangt eine Entscheidung zwischen Tageszugang und Übernachtungsreservierung. Texas State Parks veröffentlicht Zeitfenster für den Eintritt und einen getrennten Bestand an Walk-in-Zeltplätzen; diese Flächen verschmelzen nicht zu einer Nachtroute. Nutze den südlichen Loop-Trail-Ausgang nur bei aktuell offenem Tageszugang und offenen Wegen oder beobachte von einem gebuchten Stellplatz. Der Gipfel ist nach Wegschließung kein Ersatz." },
    editorialAngle: { en: "The day-use footprint and walk-in campground answer different access questions. Dark-sky designation supports the programme context, but the reservation system and same-day gate or trail status decide where a visitor may actually remain.", de: "Tagesfläche und Walk-in-Camping beantworten unterschiedliche Zugangsfragen. Die Dark-Sky-Auszeichnung stützt den Programmkontext; Reservierungssystem sowie aktueller Tor- und Wegstatus entscheiden, wo Besucher tatsächlich bleiben dürfen." },
    sections: {
      "enchanted-rock-where": { en: ["The reviewed state-park layer keeps the Loop Trail south trailhead day-use footprint separate from the walk-in camping area. That distinction prevents a day reservation from being read as permission to remain on closed trails or climb toward the summit at night. Use the marked visitor surface, obey the assigned entry window and leave when day-use instructions require.", "A walk-in tent-site reservation creates a different legal base. Carry equipment from the approved parking arrangement to the assigned site, learn the return before dark and observe beside the campsite without expanding onto nearby trail or granite. Camping inventory supports an overnight stay only at the reserved footprint; it does not reopen a closed summit route."], de: ["Die geprüfte State-Park-Karte hält den Tagesbereich am südlichen Loop-Trail-Ausgang vom Walk-in-Camping getrennt. Dadurch wird eine Tagesreservierung nicht zur Erlaubnis, auf geschlossenen Wegen zu bleiben oder nachts zum Gipfel aufzusteigen. Nutze die markierte Besucherfläche, halte das Eintrittszeitfenster ein und gehe, sobald Tagesregeln es verlangen.", "Eine Walk-in-Zeltplatzreservierung schafft eine andere legale Basis. Trage Ausrüstung von der genehmigten Parkregel zum zugewiesenen Platz, lerne den Rückweg vor der Dunkelheit und beobachte neben dem Camp ohne Ausweitung auf Weg oder Granit. Die Campingbuchung stützt die Übernachtung nur auf der reservierten Fläche und öffnet keine geschlossene Gipfelroute."] },
      "enchanted-rock-conditions": { en: ["Check the current entry window, capacity, gate, trail and camping status before travel. An archived DarkSky report records the designation and programme history, but it cannot confirm today's access. Heat, storms and exposed rock can also close or shorten trail use even when the night forecast appears clear.", "Choose the access model before arrival. If the Loop Trail area closes, leave under day-use rules rather than moving uphill. If holding a campsite, settle there during the permitted arrival period and remain inside the campground footprint. No booking or dark-sky label authorises a roadside wait, closed trail or summit alternative."], de: ["Prüfe vor der Fahrt aktuelles Eintrittsfenster, Kapazität, Tor-, Weg- und Campingstatus. Ein archivierter DarkSky-Bericht dokumentiert Auszeichnung und Programmgeschichte, bestätigt aber keinen heutigen Zugang. Hitze, Gewitter und exponierter Fels können Wege trotz klar wirkender Nachtprognose schließen oder verkürzen.", "Wähle das Zugangsmodell vor der Ankunft. Schließt der Loop-Trail-Bereich, gehst du nach Tagesregeln statt bergauf auszuweichen. Mit Campingbuchung richtest du dich im erlaubten Zeitfenster ein und bleibst auf der Campfläche. Weder Buchung noch Dark-Sky-Label erlauben Straßenrand, geschlossenen Weg oder Gipfelersatz."] },
    },
    tour: { summary: { en: "Use one current timed-entry visit at the Loop Trail south trailhead and depart under day-use rules, or reserve a walk-in tent site and observe beside that assigned campsite. Never connect the two after dark. The summit and closed trails remain outside both plans, regardless of dark-sky designation or visibility.", de: "Nutze entweder einen aktuellen Zeiteintritt am südlichen Loop-Trail-Ausgang und fahre nach Tagesregeln ab oder reserviere einen Walk-in-Zeltplatz und beobachte neben dem zugewiesenen Camp. Verbinde beide nie nach Einbruch der Dunkelheit. Gipfel und geschlossene Wege bleiben unabhängig von Dark-Sky-Auszeichnung oder Sicht außerhalb beider Pläne." }, suitability: { en: "Suitable for visitors who can follow the exact timed-entry or camping reservation, keep night activity inside its mapped footprint and abandon summit ambitions when trails or day-use access close.", de: "Geeignet für Besucher, die genaue Zeit- oder Campingreservierung befolgen, Nachtaktivität in der kartierten Fläche halten und Gipfelpläne bei Weg- oder Tageszugangsschluss aufgeben." }, steps: {
      "enchanted-rock-check": { en: "Confirm capacity, entry window, gate and trail status for day use, or verify the exact walk-in site and arrival instructions for camping. Save the applicable park map. Do not use the archived designation as evidence that the summit or Loop Trail stays open after current closure time.", de: "Bestätige Kapazität, Eintrittsfenster, Tor und Wegstatus für Tagesnutzung oder genauen Walk-in-Platz samt Anreise für Camping. Speichere die passende Parkkarte. Nutze die archivierte Auszeichnung nicht als Beleg, dass Gipfel oder Loop Trail nach aktueller Schließzeit offen bleiben." },
      "enchanted-rock-arrive": { en: "Enter during the assigned window and identify the day-use boundary or walk-in route while there is light. Keep vehicle and equipment in the authorised footprint. If capacity, signage or trail status differs from the reservation, follow the park instruction and do not shift to another granite or roadside area.", de: "Betritt den Park im zugewiesenen Fenster und erkenne Tagesbereich oder Walk-in-Weg bei Licht. Halte Fahrzeug und Ausrüstung auf der erlaubten Fläche. Weichen Kapazität, Schilder oder Wegstatus von der Reservierung ab, folge dem Parkhinweis und wechsle nicht auf andere Fels- oder Straßenflächen." },
      "enchanted-rock-observe": { en: "Use the open day-use surface only for its permitted period, or set up quietly beside the booked tent site. Shield red light and leave paths unobstructed. A view toward the summit does not make the summit part of the session once routes close.", de: "Nutze die offene Tagesfläche nur im erlaubten Zeitraum oder baue leise neben dem gebuchten Zeltplatz auf. Schirme Rotlicht ab und halte Wege frei. Ein Blick zum Gipfel macht ihn nach Wegschließung nicht zum Teil der Sitzung." },
      "enchanted-rock-leave": { en: "Depart from day use at the instructed time or remain at the booked campsite until lawful departure. Do not begin a summit walk, cross between visitor footprints or wait at the gate after closure. The correct finish follows the reservation already held.", de: "Verlasse die Tagesnutzung zur angewiesenen Zeit oder bleibe bis zur legalen Abfahrt am gebuchten Camp. Beginne keinen Gipfelweg, quere nicht zwischen Besucherflächen und warte nach Schließung nicht am Tor. Das richtige Ende folgt der vorhandenen Reservierung." },
    } },
    fieldNotes: {
      "enchanted-rock-access-note": { en: "Texas reservation pages document separate timed-entry and walk-in camping inventories. They do not grant night use of closed trails or the summit, and the two mapped footprints should never be merged into one access claim.", de: "Texanische Reservierungsseiten dokumentieren getrennte Zeitfenster und Walk-in-Campingbestände. Sie gewähren keine Nachtnutzung geschlossener Wege oder des Gipfels; beide kartierten Flächen dürfen nicht zu einem Zugangsanspruch verschmolzen werden." },
      "enchanted-rock-weather-note": { en: "Exposed granite, heat and storms can change trail conditions independently of sky clarity. Check the park's current status, not only astronomy weather, and keep a campsite-based night stationary when trails become unsuitable.", de: "Exponierter Granit, Hitze und Gewitter verändern Wege unabhängig von der Himmelsklarheit. Prüfe den aktuellen Parkstatus zusätzlich zum Astronomiewetter und halte eine Campingnacht stationär, wenn Wege ungeeignet werden." },
      "enchanted-rock-light-note": { en: "Prepare screens before the assigned window ends, direct red light at the ground and avoid illuminating rock faces or tents. Dark-sky recognition depends on visitors respecting the shared footprint rather than searching beyond it.", de: "Bereite Displays vor Ende des Zeitfensters vor, richte Rotlicht zum Boden und beleuchte weder Felswände noch Zelte. Dark-Sky-Anerkennung lebt davon, die gemeinsame Fläche zu respektieren statt außerhalb zu suchen." },
    },
    faq: [
      { question: { en: "Can a day-use reservation support summit stargazing?", de: "Erlaubt eine Tagesreservierung Sternbeobachtung am Gipfel?" }, answer: { en: "Not when the summit route or trails are closed. The official reservation material identifies entry windows and a distinct day-use footprint; it does not grant a generic right to remain on trails after closure. Observe only where and while current park instructions permit.", de: "Nicht bei geschlossener Gipfelroute oder geschlossenen Wegen. Das offizielle Reservierungsmaterial nennt Eintrittsfenster und eine eigene Tagesfläche; es gewährt kein allgemeines Recht, nach Schließung auf Wegen zu bleiben. Beobachte nur dort und so lange, wie aktuelle Parkhinweise erlauben." } },
      { question: { en: "What does a walk-in campsite booking include?", de: "Was umfasst eine Walk-in-Campingbuchung?" }, answer: { en: "It provides an assigned overnight tent-site footprint reached under the park's camping instructions. Use that site for the stationary night and keep trails clear. It does not merge with day-use access, reopen the summit or authorise another campsite or roadside setup.", de: "Sie bietet einen zugewiesenen Übernachtungsplatz, der nach den Campinghinweisen erreicht wird. Nutze diesen Platz für die stationäre Nacht und halte Wege frei. Er verschmilzt nicht mit Tageszugang, öffnet keinen Gipfel und erlaubt weder anderen Campingplatz noch Straßenaufbau." } },
    ],
  });
}

function reviseStauntonRiver(guide) {
  applyEditorialRevision(guide, {
    standfirst: { en: "Staunton River has unusually direct public guidance: Virginia DCR says the field beside the visitor center is available year-round for astronomical observation. For independent use outside designated programmes, its February 2026 guide advises visitors to call the park at least two days ahead and follow current access and parking-fee instructions. The registered October 9, 2026 Star Party and public observing night is a separate event. Use either confirmed field access or a booked campground stay, not assumptions from the Dark Sky Park label.", de: "Staunton River besitzt ungewöhnlich klare öffentliche Hinweise: Virginia DCR erklärt das Feld neben dem Besucherzentrum ganzjährig für astronomische Beobachtung verfügbar. Für selbstständige Nutzung außerhalb ausgewiesener Programme empfiehlt der Guide vom Februar 2026, den Park mindestens zwei Tage vorher anzurufen und aktuellen Zugangs- sowie Parkgebührenhinweisen zu folgen. Die angemeldete Star Party mit öffentlicher Beobachtung am 9. Oktober 2026 ist eine getrennte Veranstaltung. Nutze bestätigten Feldzugang oder gebuchten Campingaufenthalt statt Annahmen aus dem Dark-Sky-Park-Label." },
    editorialAngle: { en: "The visitor-center field is the named independent observing place, but DCR explicitly attaches advance communication and current instructions. A campground reservation is accommodation, while the dated Star Party follows its own registration.", de: "Das Feld am Besucherzentrum ist der benannte selbstständige Beobachtungsort, doch DCR verknüpft ihn ausdrücklich mit Vorabkontakt und aktuellen Hinweisen. Eine Campingreservierung ist Unterkunft; die datierte Star Party folgt ihrer eigenen Anmeldung." },
    sections: {
      "staunton-river-where": { en: ["The observing footprint is the field immediately next to the visitor center, not a general riverbank or campground loop. DCR's year-round statement gives the field a public astronomy purpose, while its current guide adds a practical step for visits outside designated programmes. Follow the parking location and access information supplied by the park and keep the visitor-center approach clear.", "The campground can support an overnight stay when reserved, but a campsite is not the same record as the observing field. Settle the assigned pitch in daylight and decide whether a confirmed field visit fits the return. The October 9 event provides a registered public programme; its calendar listing does not automatically authorise other dates under event conditions."], de: ["Die Beobachtungsfläche ist das Feld direkt neben dem Besucherzentrum und kein allgemeines Flussufer oder Campingloop. DCRs Ganzjahresaussage gibt dem Feld einen öffentlichen Astronomiezweck; der aktuelle Guide ergänzt für Besuche außerhalb ausgewiesener Programme einen praktischen Vorabschritt. Folge den vom Park genannten Park- und Zugangshinweisen und halte die Besucherzentrumzufahrt frei.", "Der Campingplatz kann mit Reservierung die Übernachtung tragen, ist aber nicht derselbe Eintrag wie das Beobachtungsfeld. Richte den Stellplatz bei Tageslicht ein und entscheide, ob ein bestätigter Feldbesuch mit Rückkehr passt. Der Termin am 9. Oktober bietet ein angemeldetes öffentliches Programm; sein Kalendereintrag autorisiert andere Daten nicht automatisch unter Veranstaltungsbedingungen."] },
      "staunton-river-conditions": { en: ["For independent field use, readers should follow DCR's advice and contact the park at least two days before arrival, then retain the current parking, fee and after-hours instructions they receive. If confirmation is absent or conditions change, postpone. The year-round description means the site has an enduring purpose, not that gates and operational details never vary.", "Weather affects an open field and a river park differently from a city forecast. Check cloud, wind, ground moisture and safe departure, then obey any programme cancellation or access change. A campground booking supplies shelter but does not overrule a closed field. Conversely, field confirmation does not create an unbooked campsite."], de: ["Für selbstständige Feldnutzung sollten Leser der DCR-Empfehlung folgen, den Park mindestens zwei Tage vorher kontaktieren und aktuelle Park-, Gebühren- und Nachtzugangshinweise speichern. Fehlt Bestätigung oder ändert sich die Lage, wird verschoben. Die Ganzjahresbeschreibung bezeichnet einen dauerhaften Zweck und bedeutet nicht, dass Tore und Betriebsdetails nie variieren.", "Wetter wirkt auf ein offenes Feld im Flusspark anders als auf eine Stadtprognose. Prüfe Wolken, Wind, Bodenfeuchte und sichere Abfahrt und befolge jede Programmabsage oder Zugangsänderung. Eine Campingbuchung bietet Schutz, überstimmt aber kein geschlossenes Feld. Umgekehrt schafft Feldbestätigung keinen ungebuchten Campingplatz."] },
    },
    tour: { summary: { en: "Arrange independent use of the visitor-center field under DCR's current guidance, including the advised two-day advance call, or register for a published programme such as the October 9, 2026 public night. Use the instructed parking, observe only on the named field and depart as directed. Keep any campground reservation separate as the overnight base.", de: "Organisiere die selbstständige Nutzung des Felds am Besucherzentrum nach aktuellem DCR-Guide einschließlich des empfohlenen Anrufs zwei Tage vorher oder melde dich zu einem veröffentlichten Programm wie dem öffentlichen Abend am 9. Oktober 2026 an. Nutze den angewiesenen Parkplatz, beobachte nur auf dem benannten Feld und fahre nach Vorgabe ab. Eine Campingbuchung bleibt getrennte Übernachtungsbasis." }, suitability: { en: "Suitable for visitors willing to obtain current field instructions, pay applicable parking fees and keep programme registration, independent access and campground accommodation as three distinct arrangements.", de: "Geeignet für Besucher, die aktuelle Feldhinweise einholen, geltende Parkgebühren zahlen und Programmanmeldung, selbstständigen Zugang sowie Campingunterkunft als drei getrennte Regelungen behandeln." }, steps: {
      "staunton-river-check": { en: "For a non-programme visit, follow the February 2026 DCR guide and contact the park at least two days ahead. Record field access, parking and fee instructions. For the October public night or another event, use that programme's registration instead; do not combine the two pathways.", de: "Folge bei einem Besuch außerhalb des Programms dem DCR-Guide vom Februar 2026 und kontaktiere den Park mindestens zwei Tage vorher. Notiere Feldzugang, Parken und Gebühren. Für den öffentlichen Oktoberabend oder eine andere Veranstaltung gilt deren Anmeldung; vermische beide Wege nicht." },
      "staunton-river-arrive": { en: "Reach the visitor-center parking under the current instruction and locate the adjacent field before dark. Pay the applicable fee and keep entrances and ordinary park use clear. If staying overnight, establish the separately booked campsite first rather than treating field parking as accommodation.", de: "Erreiche den Parkplatz am Besucherzentrum nach aktuellem Hinweis und finde das angrenzende Feld vor der Dunkelheit. Zahle die geltende Gebühr und halte Eingänge sowie normale Parknutzung frei. Bei Übernachtung richte zuerst das getrennt gebuchte Camp ein, statt Feldparkplätze als Unterkunft zu behandeln." },
      "staunton-river-observe": { en: "Remain on the named field, use shielded red light and follow event staff or independent-access conditions. Keep cables and equipment away from visitor-center circulation. Year-round astronomy use does not extend the footprint to riverbanks, roads or campground sites not assigned to the visitor.", de: "Bleibe auf dem benannten Feld, nutze abgeschirmtes Rotlicht und folge Veranstaltungs- oder Selbstzugangsbedingungen. Halte Kabel und Ausrüstung aus den Verkehrsflächen am Besucherzentrum. Ganzjährige Astronomienutzung erweitert die Fläche nicht auf Ufer, Straßen oder nicht zugewiesene Campingplätze." },
      "staunton-river-leave": { en: "Pack by the instructed finish and leave through the confirmed route, or return directly to the booked campground. Do not remain in visitor-center parking as an overnight substitute. If conditions deteriorate, end the session rather than seeking another river-park field.", de: "Packe zum angewiesenen Ende und fahre über die bestätigte Route ab oder kehre direkt zum gebuchten Camp zurück. Bleibe nicht als Übernachtungsersatz am Besucherzentrum. Verschlechtert sich die Lage, beende die Sitzung statt ein anderes Feld im Flusspark zu suchen." },
    } },
    fieldNotes: {
      "staunton-river-access-note": { en: "DCR identifies the visitor-center field for year-round astronomy and advises advance contact for independent after-hours use. That transparent condition remains part of the guide; a Dark Sky Park label alone is not a current parking or gate instruction.", de: "DCR nennt das Feld am Besucherzentrum für ganzjährige Astronomie und empfiehlt Vorabkontakt für selbstständige Nutzung außerhalb von Programmen. Diese transparente Bedingung bleibt Teil des Guides; das Dark-Sky-Park-Label allein ist keine aktuelle Park- oder Toranweisung." },
      "staunton-river-weather-note": { en: "An open field can become wet or windy while a campground remains usable. Follow a programme decision or current park guidance and treat safe vehicle departure as part of the forecast check, not as an issue after packing.", de: "Ein offenes Feld kann nass oder windig werden, während ein Camp nutzbar bleibt. Folge Programmentscheidung oder aktuellem Parkhinweis und behandle sichere Abfahrt als Teil der Wetterprüfung statt als Problem nach dem Packen." },
      "staunton-river-light-note": { en: "The observing field serves both scheduled groups and independent visitors. Prepare vehicle lights before parking, keep red light low and avoid shining toward the visitor center, campground or other telescopes.", de: "Das Beobachtungsfeld dient geplanten Gruppen und selbstständigen Besuchern. Bereite Fahrzeuglicht vor dem Parken vor, halte Rotlicht niedrig und leuchte weder zum Besucherzentrum noch zu Camp oder anderen Teleskopen." },
    },
    faq: [
      { question: { en: "Can the Staunton River field be used outside a programme?", de: "Kann das Staunton-River-Feld außerhalb eines Programms genutzt werden?" }, answer: { en: "DCR says the field is available year-round, and its February 2026 guide advises calling the park at least two days before independent use outside designated programmes. Follow that advice and the current parking, fee and access instructions; without confirmation, postpone.", de: "DCR erklärt das Feld ganzjährig verfügbar; der Guide vom Februar 2026 empfiehlt mindestens zwei Tage vor selbstständiger Nutzung außerhalb ausgewiesener Programme einen Anruf. Folge dieser Empfehlung und aktuellen Park-, Gebühren- und Zugangshinweisen; ohne Bestätigung wird verschoben." } },
      { question: { en: "Does field access include camping?", de: "Umfasst der Feldzugang Camping?" }, answer: { en: "No. The visitor-center field is an observing footprint, while overnight accommodation requires a separate campground reservation. Event registration also remains separate. Use field parking only under current instructions and return to the booked campsite or leave the park when observation ends.", de: "Nein. Das Feld am Besucherzentrum ist eine Beobachtungsfläche; Übernachtung benötigt eine getrennte Campingreservierung. Auch Veranstaltungsanmeldung bleibt separat. Nutze Feldparken nur nach aktuellem Hinweis und kehre danach zum gebuchten Camp zurück oder verlasse den Park." } },
    ],
  });
}

function reviseKissimmeePrairie(guide) {
  applyEditorialRevision(guide, {
    standfirst: { en: "Kissimmee Prairie separates reserved astronomy access from the public fallback. Florida DEP documents Astronomy Pad A as a reservable pad with red-light and no-fire rules. Visitors without that reservation or an eligible after-hours permit are directed to the pavilion beside the entrance kiosk, and the entrance closes shortly after sunset. Choose the correct footprint before arrival; the pavilion does not become a route into the closed preserve.", de: "Kissimmee Prairie trennt reservierten Astronomiezugang von der öffentlichen Ausweichfläche. Florida DEP dokumentiert Astronomy Pad A als reservierbare Plattform mit Rotlicht- und Feuerverbot. Besucher ohne diese Reservierung oder passende Nachtgenehmigung werden zum Pavillon neben dem Eingangskiosk verwiesen; die Einfahrt schließt kurz nach Sonnenuntergang. Wähle die richtige Fläche vor der Ankunft; der Pavillon wird nicht zur Route in das geschlossene Schutzgebiet." },
    editorialAngle: { en: "Pad A is for properly reserved overnight astronomy; the entrance pavilion is the documented place for visitors who cannot legally remain beyond the gate. Both require arrival before sunset and strict light discipline.", de: "Pad A dient ordnungsgemäß reservierter Nachtastronomie; der Eingangspavillon ist der dokumentierte Ort für Besucher, die nicht legal hinter dem Tor bleiben dürfen. Beide verlangen Ankunft vor Sonnenuntergang und strenge Lichtdisziplin." },
    sections: {
      "kissimmee-prairie-where": { en: ["Official accommodation GIS identifies Astronomy Pad A exactly, removing any need to infer a prairie clearing. A valid reservation or qualifying after-hours permit supports the route through the entrance and use of the assigned pad. The pad's bathroom, red-light and no-fire rules are part of that access, and the reservation never extends to other prairie tracks.", "The pavilion beside the entrance kiosk is an official alternative, not an inferior invented shoulder. DEP directs visitors there when they lack an astronomy-pad reservation or eligible after-hours permit. Use the pavilion before the entrance closes and remain on its public footprint. It grants no right to pass the gate later or drive toward Pad A."], de: ["Das offizielle Unterkunfts-GIS identifiziert Astronomy Pad A genau und macht eine abgeleitete Präriefläche unnötig. Eine gültige Reservierung oder passende Nachtgenehmigung stützt die Route durch den Eingang und die Nutzung der zugewiesenen Plattform. Bad-, Rotlicht- und Feuerregeln gehören zu diesem Zugang; die Reservierung erstreckt sich nie auf andere Präriewege.", "Der Pavillon neben dem Eingangskiosk ist eine offizielle Alternative und kein erfundener Seitenstreifen. DEP verweist Besucher ohne Astronomy-Pad-Reservierung oder passende Nachtgenehmigung dorthin. Nutze den Pavillon vor Eingangsschluss und bleibe auf seiner öffentlichen Fläche. Er erlaubt weder spätere Tordurchfahrt noch Fahrt zu Pad A."] },
      "kissimmee-prairie-conditions": { en: ["Arrival before sunset is essential because the entrance closes shortly afterward. Verify the pad reservation, permit eligibility and gate timing before the drive; a clear forecast cannot solve a missed closure. At the pavilion, plan a finish and departure that follows the entrance-area rules rather than assuming access deeper into the preserve.", "Fire and white light are explicit operational boundaries at the astronomy pad. Check storms, wind, insects and ground conditions, then bring only equipment manageable under red light. If weather spoils the night, remain at the reserved pad or leave from the pavilion as required. Do not search the prairie by vehicle."], de: ["Ankunft vor Sonnenuntergang ist wesentlich, weil die Einfahrt kurz danach schließt. Prüfe Pad-Reservierung, Genehmigungsberechtigung und Torzeit vor der Fahrt; eine klare Prognose löst keinen verpassten Schluss. Lege am Pavillon Ende und Abfahrt nach Regeln des Eingangsbereichs fest, statt Zugang tiefer ins Schutzgebiet anzunehmen.", "Feuer und Weißlicht sind ausdrückliche Betriebsgrenzen auf der Astronomieplattform. Prüfe Gewitter, Wind, Insekten und Boden und bringe nur Ausrüstung mit, die unter Rotlicht handhabbar bleibt. Verhindert Wetter die Nacht, bleibe am reservierten Pad oder fahre vom Pavillon regelgerecht ab. Suche die Prärie nicht per Fahrzeug ab."] },
    },
    tour: { summary: { en: "Reserve Astronomy Pad A and arrive before sunset for the full overnight astronomy plan, following red-light, bathroom and no-fire rules. Without that reservation or qualifying permit, use only the entrance-kiosk pavilion and remain outside the closed interior. Never treat the pavilion as a waiting point for later access or the pad as available without the proper booking.", de: "Reserviere Astronomy Pad A und komme vor Sonnenuntergang für den vollständigen Nachtplan an; befolge Rotlicht-, Bad- und Feuerregeln. Ohne Reservierung oder passende Genehmigung nutzt du ausschließlich den Pavillon am Eingangskiosk und bleibst außerhalb des geschlossenen Inneren. Behandle den Pavillon nie als Wartepunkt für späteren Zutritt und das Pad nie als ungebucht verfügbar." }, suitability: { en: "Suitable for visitors who can match their reservation or permit to the correct footprint, arrive before gate closure and observe under red-light and no-fire constraints without roaming the preserve.", de: "Geeignet für Besucher, die Reservierung oder Genehmigung der richtigen Fläche zuordnen, vor Torschluss ankommen und unter Rotlicht- und Feuerverbot beobachten, ohne das Schutzgebiet abzufahren." }, steps: {
      "kissimmee-prairie-check": { en: "Verify Astronomy Pad A in the booking and confirm permit, gate, bathroom, red-light and no-fire instructions. If those requirements are not met, select the entrance-kiosk pavilion before travel. Save the exact footprint and do not plan to negotiate the distinction after sunset.", de: "Bestätige Astronomy Pad A in der Buchung und prüfe Genehmigungs-, Tor-, Bad-, Rotlicht- und Feuerhinweise. Sind die Anforderungen nicht erfüllt, wähle vor der Fahrt den Pavillon am Eingangskiosk. Speichere die genaue Fläche und plane nicht, die Unterscheidung nach Sonnenuntergang zu klären." },
      "kissimmee-prairie-arrive": { en: "Reach the entrance before sunset. Proceed to Pad A only under the valid reservation or permit, otherwise stop at the pavilion beside the kiosk. Identify parking, boundaries and departure route while visible, and never wait for a closed gate to reopen for astronomy access.", de: "Erreiche den Eingang vor Sonnenuntergang. Fahre nur mit gültiger Reservierung oder Genehmigung zu Pad A; andernfalls bleibe am Pavillon neben dem Kiosk. Erkenne Parken, Grenzen und Abfahrt bei Licht und warte nie auf ein geschlossenes Tor für Astronomiezugang." },
      "kissimmee-prairie-observe": { en: "At Pad A, use red light only, keep the bathroom route clear and light no fire. At the pavilion, contain equipment to the entrance footprint and do not cross into the preserve. Both settings require quiet and awareness of weather and wildlife.", de: "Nutze auf Pad A nur Rotlicht, halte den Weg zum Bad frei und entzünde kein Feuer. Begrenze am Pavillon die Ausrüstung auf den Eingangsbereich und betritt das Schutzgebiet nicht. Beide Umgebungen verlangen Ruhe sowie Aufmerksamkeit für Wetter und Wildtiere." },
      "kissimmee-prairie-leave": { en: "Follow the reserved pad's checkout or the pavilion's entrance-area departure instructions. Pack fully before vehicle lights are needed and stay on the known route. A cloudy session does not authorise movement between the two footprints or exploration beyond the gate.", de: "Folge der Abreise des reservierten Pads oder den Regeln des Eingangsbereichs am Pavillon. Packe vollständig, bevor Fahrzeuglicht nötig wird, und bleibe auf der bekannten Route. Eine bewölkte Sitzung erlaubt weder Wechsel zwischen beiden Flächen noch Erkundung hinter dem Tor." },
    } },
    fieldNotes: {
      "kissimmee-prairie-access-note": { en: "The official record distinguishes exact Pad A from the pavilion beside the kiosk. Reservation or eligible after-hours permit governs interior access; visitors without it are directed to the entrance footprint, not to another prairie location.", de: "Der offizielle Eintrag trennt das genaue Pad A vom Pavillon am Kiosk. Reservierung oder passende Nachtgenehmigung regelt Innenzugang; Besucher ohne sie werden zur Eingangsfläche und nicht an einen anderen Prärieort verwiesen." },
      "kissimmee-prairie-weather-note": { en: "Storms, wind and wet ground can make the exposed prairie unsuitable even when access is valid. Decide before gate closure and keep the cancellation outcome at the booked pad or public pavilion instead of driving deeper for clearer sky.", de: "Gewitter, Wind und nasser Boden können die offene Prärie trotz gültigem Zugang ungeeignet machen. Entscheide vor Torschluss und bleibe bei Absage am gebuchten Pad oder öffentlichen Pavillon, statt tiefer nach klarem Himmel zu fahren." },
      "kissimmee-prairie-light-note": { en: "Pad A specifically requires red light, so prepare screens and vehicle settings before sunset. The same restraint benefits the pavilion: keep light low, brief and inward rather than illuminating the gate, prairie or other observers.", de: "Pad A verlangt ausdrücklich Rotlicht; bereite Displays und Fahrzeugeinstellungen vor Sonnenuntergang vor. Dieselbe Zurückhaltung gilt am Pavillon: Licht bleibt schwach, kurz und nach innen statt Tor, Prärie oder andere Beobachter zu beleuchten." },
    },
    faq: [
      { question: { en: "Who may use Astronomy Pad A after sunset?", de: "Wer darf Astronomy Pad A nach Sonnenuntergang nutzen?" }, answer: { en: "Visitors need the proper pad reservation or eligible after-hours permit and must arrive before the entrance closes. The official rules include red-light and no-fire requirements. Without that access basis, use the pavilion beside the entrance kiosk rather than attempting to reach the pad.", de: "Besucher benötigen die richtige Pad-Reservierung oder passende Nachtgenehmigung und müssen vor Eingangsschluss ankommen. Die offiziellen Regeln umfassen Rotlicht und Feuerverbot. Ohne diese Zugangsgrundlage nutzt du den Pavillon neben dem Eingangskiosk statt das Pad anzufahren." } },
      { question: { en: "Is the entrance pavilion a route into the park at night?", de: "Ist der Eingangspavillon eine Route in den Park bei Nacht?" }, answer: { en: "No. DEP identifies it as the observing place for visitors without a reservation or qualifying after-hours permit. Remain within that entrance footprint and follow its departure rules. The pavilion does not provide later gate access or permission to drive toward another prairie site.", de: "Nein. DEP nennt ihn als Beobachtungsort für Besucher ohne Reservierung oder passende Nachtgenehmigung. Bleibe auf dieser Eingangsfläche und folge den Abfahrtsregeln. Der Pavillon vermittelt weder späteren Tordurchgang noch die Erlaubnis, zu einem anderen Prärieort zu fahren." } },
    ],
  });
}

function reviseBigCypress(guide) {
  applyEditorialRevision(guide, {
    standfirst: { en: "Big Cypress supports year-round stargazing through two legally distinct formats. National Park Service ranger programmes use the mapped south end of Seagrape Drive on published dates, while Midway Campground provides a separate year-round reservable overnight base with quiet hours. Attend one current programme or observe from one booked campsite. Neither arrangement permits entry to another boardwalk, road shoulder or closed day-use area after dark.", de: "Big Cypress unterstützt ganzjährige Sternbeobachtung über zwei rechtlich getrennte Formate. Programme des National Park Service nutzen an veröffentlichten Terminen den kartierten südlichen Abschnitt von Seagrape Drive; Midway Campground bietet eine getrennte ganzjährig reservierbare Übernachtungsbasis mit Ruhezeiten. Besuche ein aktuelles Programm oder beobachte von einem gebuchten Stellplatz. Keine Regelung erlaubt nachts ein anderes Boardwalk, einen Straßenrand oder geschlossenen Tagesbereich." },
    editorialAngle: { en: "Seagrape Drive is an event footprint whose date and ranger instructions create access. Midway is accommodation governed by reservation and quiet hours. A programme cancellation never transfers visitors to campground space or an unrelated preserve attraction.", de: "Seagrape Drive ist eine Veranstaltungsfläche, deren Datum und Rangerhinweise Zugang schaffen. Midway ist Unterkunft unter Reservierungs- und Ruhezeiten. Eine Programmabsage überträgt Besucher nie auf Campingfläche oder eine andere Schutzgebietsattraktion." },
    sections: {
      "big-cypress-where": { en: ["NPS maps the ranger programme at the south end of Seagrape Drive and publishes current event information. That exact event footprint replaces any assumption that the whole road or nearby day-use facilities are open at night. Use it only when a current programme names the date, arrival and parking arrangement, and remain with the ranger-led group.", "Midway Campground has a separate exact NPS coordinate and year-round visitor information, while Recreation.gov supplies reservation and quiet-hour rules. A booked site supports a stationary overnight observation beside the assigned campsite. It does not confer access to Seagrape Drive outside a programme or to another preserve boardwalk after closure."], de: ["NPS kartiert das Rangerprogramm am südlichen Ende von Seagrape Drive und veröffentlicht aktuelle Veranstaltungsinformationen. Diese genaue Fläche ersetzt jede Annahme, die ganze Straße oder nahe Tagesanlagen seien nachts offen. Nutze sie nur, wenn ein aktuelles Programm Datum, Ankunft und Parken nennt, und bleibe bei der Rangergruppe.", "Midway Campground besitzt eine getrennte genaue NPS-Koordinate und ganzjährige Besucherinformation; Recreation.gov liefert Reservierungs- und Ruhezeiten. Ein gebuchter Platz stützt stationäre Nachtbeobachtung neben dem Stellplatz. Er gewährt weder Seagrape-Zugang außerhalb eines Programms noch den Zutritt zu einem anderen Boardwalk nach Schließung."] },
      "big-cypress-conditions": { en: ["For Seagrape Drive, the published programme is the operational forecast: confirm that the event remains listed and follow ranger weather or cancellation instructions. Year-round stargazing promotion describes the preserve's opportunity, not a standing gate rule. If the event does not run, leave rather than selecting another NPS attraction.", "At Midway, check reservation, current campground conditions and quiet hours before arrival. Wet-season weather, insects and storms may make outdoor observing impractical while the campsite remains the lawful base. Keep the vehicle parked and lower activity when quiet hours begin; do not use cloud gaps as a reason for a night drive."], de: ["Für Seagrape Drive ist das veröffentlichte Programm der Betriebsrahmen: Bestätige den weiterhin gelisteten Termin und folge Rangerhinweisen zu Wetter oder Absage. Die ganzjährige Stargazing-Bewerbung beschreibt die Möglichkeit im Schutzgebiet und keine dauerhafte Torregel. Findet das Ereignis nicht statt, fahre ab statt eine andere NPS-Attraktion zu wählen.", "Prüfe für Midway Reservierung, aktuelle Campingbedingungen und Ruhezeiten vor der Ankunft. Regenzeit, Insekten und Gewitter können Außenbeobachtung verhindern, während der Stellplatz legale Basis bleibt. Lass das Fahrzeug stehen und reduziere Aktivität mit Beginn der Ruhezeit; nutze Wolkenlücken nicht als Grund für Nachtfahrt."] },
    },
    tour: { summary: { en: "Choose a currently published ranger programme at Seagrape Drive and follow its meeting and finish, or reserve Midway Campground and observe quietly beside the assigned site under quiet-hour rules. Keep the two plans separate. A cancelled programme, full campground or cloudy pitch does not authorise another boardwalk, shoulder or day-use area.", de: "Wähle ein aktuell veröffentlichtes Rangerprogramm an Seagrape Drive und folge Treffpunkt sowie Ende oder reserviere Midway Campground und beobachte leise neben dem Stellplatz unter Ruhezeiten. Halte beide Pläne getrennt. Abgesagtes Programm, volles Camp oder bewölkter Platz erlaubt kein anderes Boardwalk, keinen Randstreifen und keinen Tagesbereich." }, suitability: { en: "Suitable for registered programme participants or booked campers who can accept ranger weather decisions, campground quiet hours and a stationary night without searching the preserve for another opening.", de: "Geeignet für angemeldete Programmteilnehmer oder gebuchte Camper, die Ranger-Wetterentscheidungen, Campingruhezeiten und eine stationäre Nacht ohne Suche nach anderer Lichtung akzeptieren." }, steps: {
      "big-cypress-check": { en: "For Seagrape Drive, select a live NPS programme listing and save its time and mapped meeting footprint. For Midway, verify the campsite reservation and quiet hours. Do not rely on general year-round stargazing language to bridge missing event or accommodation access.", de: "Wähle für Seagrape Drive einen aktuellen NPS-Programmeintrag und speichere Zeit sowie kartierte Trefffläche. Bestätige für Midway Stellplatz und Ruhezeiten. Nutze allgemeine ganzjährige Stargazing-Angaben niemals, um fehlenden Veranstaltungs- oder Unterkunftszugang künstlich zu überbrücken." },
      "big-cypress-arrive": { en: "Reach the ranger meeting at the instructed time or check into the assigned Midway campsite before dark. Keep parking and unloading inside that one visitor footprint. If signs or instructions differ, follow NPS direction and do not relocate to a road shoulder or closed facility.", de: "Erreiche den Rangertreff zur angewiesenen Zeit oder richte dich vor Dunkelheit auf dem zugewiesenen Midway-Platz ein. Halte Parken und Ausladen innerhalb dieser Besucherfläche. Weichen Schilder oder Hinweise ab, folge NPS und wechsle nicht zu Straßenrand oder geschlossener Anlage." },
      "big-cypress-observe": { en: "At Seagrape, remain with the programme and follow ranger light rules. At Midway, shield red light, respect neighbouring campers and quiet hours, and keep camp roads clear. The wetland beyond either footprint is not an observing extension.", de: "Bleibe an Seagrape beim veröffentlichten Programm und folge den Ranger-Lichtregeln. Schirme in Midway Rotlicht ab, respektiere Nachbarcamper und Ruhezeiten und halte sämtliche Campstraßen frei. Das geschützte Feuchtgebiet außerhalb beider Flächen ist keine zusätzliche Beobachtungserweiterung." },
      "big-cypress-leave": { en: "Depart Seagrape when the ranger programme ends or remain at the booked Midway site until lawful checkout. Do not use the return for a stop at another boardwalk or day-use pullout. Finish with the same access arrangement that began the night.", de: "Verlasse Seagrape zum Ende des Rangerprogramms oder bleibe bis zur legalen Abreise auf dem gebuchten Midway-Platz. Nutze den Rückweg nicht für ein anderes Boardwalk oder einen Tageshalt. Beende die Nacht mit derselben Zugangsregel, mit der sie begann." },
    } },
    fieldNotes: {
      "big-cypress-access-note": { en: "NPS precisely maps the Seagrape programme and Midway Campground. One requires a current ranger event; the other requires a campsite reservation. Neither exact coordinate creates access to surrounding closed or day-use land.", de: "NPS kartiert Seagrape-Programm und Midway Campground genau. Das eine benötigt einen aktuellen Rangertermin, das andere eine Campingreservierung. Keine Koordinate schafft Zugang zu umliegendem geschlossenem oder Tagesgelände." },
      "big-cypress-weather-note": { en: "Ranger cancellation controls the programme, while campground conditions govern Midway. Wet-season storms and insects may stop observation without invalidating a lawful stay; remain sheltered rather than driving for another clear patch.", de: "Rangerabsage steuert das Programm, Campingbedingungen Midway. Gewitter und Insekten der Regenzeit können Beobachtung verhindern, ohne den legalen Aufenthalt aufzuheben; bleibe geschützt statt nach einer klaren Stelle zu fahren." },
      "big-cypress-light-note": { en: "Both settings protect dark wetland habitat as well as observers. Use the ranger-specified light level or brief shielded red light at camp, and avoid vehicle beams toward vegetation, water or neighbouring sites.", de: "Beide Umgebungen schützen dunkles Feuchtgebiet und Beobachter. Nutze die vom Ranger verlangte Lichtstufe oder kurzes abgeschirmtes Rotlicht im Camp und vermeide Fahrzeugstrahlen zu Vegetation, Wasser oder Nachbarplätzen." },
    },
    faq: [
      { question: { en: "Is Seagrape Drive independently open for stargazing?", de: "Ist Seagrape Drive selbstständig für Sternbeobachtung geöffnet?" }, answer: { en: "The reviewed evidence maps it as the location of current NPS ranger programmes. Use it when a published event supplies the date and instructions, not as a standing independent-access site. If the programme is absent or cancelled, do not wait there or choose another closed day-use area.", de: "Der geprüfte Beleg kartiert den Ort für aktuelle NPS-Rangerprogramme. Nutze ihn, wenn eine veröffentlichte Veranstaltung Datum und Hinweise liefert, nicht als dauerhaft selbstständig zugänglichen Platz. Fehlt das Programm oder fällt es aus, warte dort nicht und wähle keinen geschlossenen Tagesbereich." } },
      { question: { en: "Can a Midway booking be used at other Big Cypress sites?", de: "Gilt eine Midway-Buchung an anderen Big-Cypress-Orten?" }, answer: { en: "No. It provides one assigned campground footprint governed by reservation and quiet hours. Observe beside that site and keep the vehicle parked. The booking does not grant event access at Seagrape Drive or after-hours use of boardwalks, shoulders and day-use areas.", de: "Nein. Sie bietet eine zugewiesene Campfläche unter Reservierungs- und Ruhezeiten. Beobachte neben diesem Platz und lass das Fahrzeug stehen. Die Buchung gewährt weder Veranstaltungszugang an Seagrape Drive noch Nachtnutzung von Boardwalks, Randstreifen oder Tagesbereichen." } },
    ],
  });
}

function reviseLassenVolcanic(guide) {
  applyEditorialRevision(guide, {
    standfirst: { en: "Lassen Volcanic National Park explicitly permits stargazing wherever the sky is visible and recommends named roadside settings including Manzanita Lake and the Lassen Peak trailhead parking area. That broad permission still separates observing from sleeping: ordinary parking areas and pullouts are not campgrounds. Choose one currently open road-access site, verify snow and closures, observe from the established surface and leave for lawful accommodation rather than remaining overnight.", de: "Der Lassen Volcanic National Park erlaubt Sternbeobachtung ausdrücklich überall dort, wo der Himmel sichtbar ist, und empfiehlt benannte Straßenorte wie Manzanita Lake und den Parkplatz am Lassen Peak Trailhead. Diese breite Erlaubnis trennt Beobachtung weiterhin von Übernachtung: Normale Parkflächen und Haltebuchten sind keine Campingplätze. Wähle einen aktuell über Straße offenen Ort, prüfe Schnee und Sperrungen, beobachte auf der bestehenden Fläche und fahre danach zu legaler Unterkunft statt dort zu übernachten." },
    editorialAngle: { en: "Manzanita Lake is the lower-complexity primary site; the higher Lassen Peak parking area depends more heavily on mountain road and snow status. Neither recommendation converts a roadside viewing stop into overnight camping.", de: "Manzanita Lake ist der weniger komplexe Hauptort; der höhere Lassen-Peak-Parkplatz hängt stärker von Bergstraße und Schneestatus ab. Keine Empfehlung verwandelt einen Straßen-Beobachtungshalt in Übernachtungscamping." },
    sections: {
      "lassen-volcanic-where": { en: ["The NPS stargazing page directly names Manzanita Lake as a viewing option, making an established lake-area visitor surface more defensible than an arbitrary pullout. Use current parking and signs, keep shoreline access clear and decide the return before darkness. If overnight shelter is required, reserve a lawful campground separately; the viewing area itself is not accommodation.", "The Lassen Peak trailhead parking area is also recommended, but its higher mountain-road context creates a separate decision. Verify that the road, parking area and return are open and free of prohibitive snow or closure. Do not add it after Manzanita Lake because clouds appear locally; each site deserves one daylight-checked approach."], de: ["Die NPS-Stargazing-Seite nennt Manzanita Lake direkt als Beobachtungsoption; eine bestehende Besucherfläche am See ist daher belastbarer als eine beliebige Haltebucht. Nutze aktuelle Parkplätze und Schilder, halte Uferzugänge frei und entscheide den Rückweg vor der Dunkelheit. Wird Übernachtung benötigt, reserviere getrennt einen legalen Campingplatz; die Beobachtungsfläche ist keine Unterkunft.", "Auch der Parkplatz am Lassen Peak Trailhead wird empfohlen, doch sein Bergstraßenkontext schafft eine getrennte Entscheidung. Bestätige offene Straße, Parkfläche und Rückweg ohne verhindernden Schnee oder Sperre. Ergänze ihn nicht nach Manzanita Lake, nur weil dort Wolken erscheinen; jeder Ort benötigt einen bei Tageslicht geprüften Zugang."] },
      "lassen-volcanic-conditions": { en: ["Road, snow, wildfire and closure information can change which NPS recommendation is usable. Check current conditions for the selected elevation before entering the park, and never infer that a named stargazing site is reachable because the lower entrance is open. The historical darkness context cannot measure snowbanks, smoke or a closed mountain road.", "Observing permission ends where camping rules begin. Pack for a defined session and a direct return to a campground or lodging. If fatigue, weather or road uncertainty makes that return doubtful, do not start. Remaining in an ordinary pullout or trailhead lot overnight is not the safety solution because camping there is not permitted."], de: ["Straßen-, Schnee-, Brand- und Sperrinformationen können verändern, welche NPS-Empfehlung nutzbar ist. Prüfe aktuelle Bedingungen für die gewählte Höhe vor Parkeinfahrt und leite Erreichbarkeit nie aus einem offenen unteren Eingang ab. Historischer Dunkelheitskontext misst weder Schneewälle noch Rauch oder gesperrte Bergstraße.", "Beobachtungserlaubnis endet dort, wo Campingregeln beginnen. Packe für eine definierte Sitzung und direkte Rückkehr zu Camp oder Unterkunft. Machen Müdigkeit, Wetter oder Straßenunsicherheit diesen Rückweg fraglich, beginne nicht. Übernachtung in gewöhnlicher Haltebucht oder Trailhead-Parkplatz ist keine Sicherheitslösung, weil Camping dort nicht erlaubt ist."] },
    },
    tour: { summary: { en: "Use Manzanita Lake as one checked roadside viewing destination, or select the Lassen Peak trailhead parking area on a separately verified open-road night. Arrive before dark, remain on the established visitor surface and return to a lawful campground or lodging after observation. Do not sleep at the pullout or add the second site after dark.", de: "Nutze Manzanita Lake als ein geprüftes Straßen-Beobachtungsziel oder wähle den Parkplatz am Lassen Peak Trailhead in einer getrennt bestätigten Nacht mit offener Straße. Komme vor Dunkelheit an, bleibe auf der bestehenden Besucherfläche und kehre danach zu legalem Camp oder Unterkunft zurück. Schlafe nicht am Halt und ergänze nachts keinen zweiten Ort." }, suitability: { en: "Suitable for visitors who can verify elevation-specific roads and snow, separate viewing from camping and complete a direct return without using an ordinary parking area as overnight shelter.", de: "Geeignet für Besucher, die höhenspezifische Straße und Schnee prüfen, Beobachtung von Camping trennen und direkt zurückkehren, ohne normalen Parkplatz als Nachtunterkunft zu nutzen." }, steps: {
      "lassen-volcanic-check": { en: "Choose Manzanita Lake or Lassen Peak before travel and check current NPS road, snow, fire and closure information for that route. Confirm lawful accommodation for after the session. General permission to stargaze does not confirm that every road or recommended parking area is open.", de: "Wähle Manzanita Lake oder Lassen Peak vor der Fahrt und prüfe aktuelle NPS-Angaben zu Straße, Schnee, Feuer und Sperrung für diese Route. Bestätige legale Unterkunft danach. Die allgemeine Stargazing-Erlaubnis bestätigt nicht jede Straße oder empfohlene Parkfläche als offen." },
      "lassen-volcanic-arrive": { en: "Reach the established parking or lake visitor area in daylight and identify the same return road. Park only where current signs permit and keep trail, shore and traffic access clear. If snow, barriers or notices differ from the plan, turn back rather than selecting another pullout.", de: "Erreiche bestehende Park- oder Seebesucherfläche bei Tageslicht und erkenne dieselbe Rückstraße. Parke nur nach aktuellen Schildern und halte Weg-, Ufer- und Verkehrszugang frei. Weichen Schnee, Barrieren oder Hinweise ab, kehre um statt eine andere Haltebucht zu wählen." },
      "lassen-volcanic-observe": { en: "Observe from the named established surface, using brief downward red light and compact equipment. Do not move onto closed trails or vegetation for a wider horizon. The NPS recommendation supports viewing at the site, while all resource and parking rules continue after dark.", de: "Beobachte von der benannten bestehenden Fläche mit kurzem Rotlicht nach unten und kompakter Ausrüstung. Wechsle für weiteren Horizont nicht auf geschlossene Wege oder Vegetation. Die NPS-Empfehlung unterstützt Beobachtung am Ort; Ressourcen- und Parkregeln gelten nachts weiter." },
      "lassen-volcanic-leave": { en: "Pack before road conditions, cold or fatigue threaten the planned return and drive directly to the lawful overnight base. Do not remain at the trailhead or pullout to sleep and do not add the second recommended site. Observing ends before camping would begin.", de: "Packe, bevor Straße, Kälte oder Müdigkeit den geplanten Rückweg gefährden, und fahre direkt zur legalen Übernachtungsbasis. Bleibe nicht zum Schlafen am Trailhead oder Halt und ergänze keinen zweiten Ort. Beobachtung endet, bevor Camping beginnen würde." },
    } },
    fieldNotes: {
      "lassen-volcanic-access-note": { en: "NPS directly supports visible-sky stargazing and names Manzanita Lake and Lassen Peak parking. It also confines overnight camping to campgrounds, so the recommendation is for viewing, not sleeping at ordinary parking areas.", de: "NPS unterstützt Sternbeobachtung bei sichtbarem Himmel direkt und nennt Manzanita Lake sowie Lassen-Peak-Parken. Übernachtungscamping bleibt auf Camps beschränkt; die Empfehlung gilt für Beobachtung und nicht Schlafen auf normalen Parkflächen." },
      "lassen-volcanic-weather-note": { en: "Elevation makes the two sites respond differently to snow, wind and road closure. Check the selected route itself and keep a return margin; lower-park access does not prove the summit road or parking area usable.", de: "Die Höhe lässt beide Orte unterschiedlich auf Schnee, Wind und Straßensperrung reagieren. Prüfe die gewählte Route selbst und halte Rückkehrreserve; unterer Parkzugang belegt keine nutzbare Gipfelstraße oder Parkfläche." },
      "lassen-volcanic-light-note": { en: "Roadside viewing still occurs inside a national park. Prepare vehicle lights before stopping, use shielded red light and avoid illuminating water, forest, trailheads or approaching drivers.", de: "Straßennahe Beobachtung findet weiterhin im Nationalpark statt. Bereite Fahrzeuglicht vor dem Halt vor, nutze abgeschirmtes Rotlicht und beleuchte weder Wasser noch Wald, Trailheads oder ankommende Fahrer." },
    },
    faq: [
      { question: { en: "Where does NPS recommend stargazing at Lassen?", de: "Wo empfiehlt NPS Sternbeobachtung in Lassen?" }, answer: { en: "NPS permits stargazing wherever the sky is visible and specifically recommends settings including Manzanita Lake and the Lassen Peak trailhead parking area. Use one currently open established surface, with road, snow and closure checks matched to that elevation.", de: "NPS erlaubt Sternbeobachtung überall bei sichtbarem Himmel und empfiehlt ausdrücklich Orte wie Manzanita Lake und den Parkplatz am Lassen Peak Trailhead. Nutze eine aktuell offene bestehende Fläche und gleiche Straßen-, Schnee- und Sperrprüfung mit dieser Höhe ab." } },
      { question: { en: "Can visitors sleep at a Lassen viewing parking area?", de: "Dürfen Besucher auf einem Lassen-Beobachtungsparkplatz schlafen?" }, answer: { en: "No ordinary pullout or parking recommendation is presented as camping. Overnight camping remains limited to campgrounds. Plan a defined observing session and return to a reserved campsite or lawful lodging rather than using the vehicle at Manzanita Lake or the trailhead as accommodation.", de: "Keine normale Halte- oder Parkempfehlung wird als Camping dargestellt. Übernachtungscamping bleibt auf Campingplätze beschränkt. Plane eine definierte Sitzung und kehre zu reserviertem Camp oder legaler Unterkunft zurück, statt Fahrzeug am See oder Trailhead als Unterkunft zu nutzen." } },
    ],
  });
}

function reviseDinosaurNationalMonument(guide) {
  applyEditorialRevision(guide, {
    standfirst: { en: "Dinosaur National Monument documents two official night-use settings with different risk. Near Split Mountain Campground, NPS identifies a stargazing spot and directs non-campers to the adjacent day-use parking area. Echo Park combines camping and stargazing, but its steep unpaved road can become impassable when wet and may require high clearance or four-wheel drive. Choose one area, match vehicle and booking to it, and never transfer between them after dark.", de: "Dinosaur National Monument dokumentiert zwei offizielle Nachtorte mit unterschiedlichem Risiko. Nahe Split Mountain Campground nennt NPS einen Sternbeobachtungsplatz und verweist Nichtcamper auf den angrenzenden Tagesparkplatz. Echo Park verbindet Camping und Sternbeobachtung, doch seine steile unbefestigte Straße kann bei Nässe unpassierbar werden und hohe Bodenfreiheit oder Allrad verlangen. Wähle einen Bereich, passe Fahrzeug und Buchung an und wechsle nachts nie zwischen beiden." },
    editorialAngle: { en: "Split Mountain offers a designated viewing arrangement with separate parking for non-campers. Echo Park is a booked overnight expedition whose access road, weather and vehicle suitability must be settled in daylight.", de: "Split Mountain bietet eine ausgewiesene Beobachtungsregel mit getrenntem Parken für Nichtcamper. Echo Park ist eine gebuchte Übernachtungsexpedition, deren Straße, Wetter und Fahrzeugeignung bei Tageslicht geklärt werden müssen." },
    sections: {
      "dinosaur-national-monument-where": { en: ["NPS publishes an exact event coordinate for the designated spot near Split Mountain Campground. Campers use their assigned campground setting, while visitors without a campsite are directed to the adjacent day-use parking area. That distinction keeps observation possible without treating a campground road or unassigned site as public overflow.", "Echo Park is a separate camping and stargazing area reached by a steep unpaved road. NPS warns that wet conditions can make it impassable and that high clearance or four-wheel drive may be needed. Its attraction is inseparable from a valid campsite, suitable vehicle and daylight access; it is never a spontaneous fallback from Split Mountain."], de: ["NPS veröffentlicht eine genaue Veranstaltungskoordinate für den ausgewiesenen Platz nahe Split Mountain Campground. Camper nutzen ihren zugewiesenen Campingkontext; Besucher ohne Stellplatz werden auf den angrenzenden Tagesparkplatz verwiesen. Diese Trennung ermöglicht Beobachtung, ohne Campstraße oder unzugewiesenen Platz zur öffentlichen Ausweichfläche zu machen.", "Echo Park ist ein getrenntes Camping- und Stargazing-Gebiet an einer steilen unbefestigten Straße. NPS warnt, dass Nässe sie unpassierbar machen kann und hohe Bodenfreiheit oder Allrad nötig sein können. Der Ort ist untrennbar mit gültigem Stellplatz, passendem Fahrzeug und Tageszugang verbunden und niemals spontaner Ersatz für Split Mountain."] },
      "dinosaur-national-monument-conditions": { en: ["At Split Mountain, confirm current opening, event or viewing instructions, campground status and the rule for day-use parking. Non-campers need a lawful departure rather than an overnight stay in that parking area. Campers must respect campground quiet hours. The exact coordinate locates the activity but does not erase either distinction.", "For Echo Park, weather and road surface are the access decision. Check recent rain, current NPS road information, vehicle requirements and campsite booking before descending. Once there, remain overnight at the assigned camp and leave in daylight. If any condition is doubtful, do not test the road or reroute to Split Mountain after dark."], de: ["Bestätige bei Split Mountain aktuelle Öffnung, Veranstaltungs- oder Beobachtungshinweise, Campingstatus und die Regel für den Tagesparkplatz. Nichtcamper benötigen eine legale Abfahrt statt Übernachtung dort. Camper beachten Ruhezeiten. Die genaue Koordinate verortet die Aktivität, hebt aber keine Unterscheidung auf.", "Für Echo Park entscheiden Wetter und Straßenoberfläche über den Zugang. Prüfe jüngsten Regen, aktuelle NPS-Straßenangaben, Fahrzeuganforderung und Campingbuchung vor der Abfahrt. Bleibe danach über Nacht am zugewiesenen Camp und fahre bei Tageslicht ab. Ist etwas fraglich, teste weder Straße noch nächtliche Umleitung nach Split Mountain."] },
    },
    tour: { summary: { en: "Use the designated Split Mountain stargazing area with the correct campground site or adjacent day-use parking and finish according to that status. Plan Echo Park on a different night with a booked campsite, suitable vehicle, dry-road confirmation and daylight descent. The two official areas are alternatives, not a night circuit.", de: "Nutze den ausgewiesenen Split-Mountain-Beobachtungsbereich mit richtigem Campingplatz oder angrenzendem Tagesparkplatz und beende nach diesem Status. Plane Echo Park an einer anderen Nacht mit gebuchtem Camp, geeignetem Fahrzeug, bestätigter trockener Straße und Tagesabfahrt hinunter. Beide offiziellen Bereiche sind Alternativen und keine Nachtrunde." }, suitability: { en: "Suitable for visitors who can distinguish camper and non-camper parking at Split Mountain or fully prepare Echo Park's steep unpaved approach, then remain at one site for the night.", de: "Geeignet für Besucher, die Camper- und Nichtcamperparken bei Split Mountain unterscheiden oder Echo Parks steile unbefestigte Zufahrt vollständig vorbereiten und dann eine Nacht an einem Ort bleiben." }, steps: {
      "dinosaur-national-monument-check": { en: "Choose Split Mountain or Echo Park before entering the monument. For Split Mountain, verify current viewing and parking instructions. For Echo Park, confirm campsite, road dryness and vehicle suitability. Save the exact official area and reject any plan that requires an after-dark transfer.", de: "Wähle Split Mountain oder Echo Park vor Parkeinfahrt. Prüfe für Split Mountain aktuelle Beobachtungs- und Parkhinweise; für Echo Park Stellplatz, Straßentrockenheit und Fahrzeugeignung. Speichere den genauen offiziellen Bereich und verwerfe jeden Plan mit Nachttransfer." },
      "dinosaur-national-monument-arrive": { en: "At Split Mountain, park in the assigned campsite or adjacent day-use area according to status. At Echo Park, descend the steep unpaved road only in daylight under current NPS guidance. If signs, moisture or vehicle capability conflict with the plan, turn back before committing.", de: "Parke bei Split Mountain je nach Status auf zugewiesenem Campingplatz oder angrenzendem Tagesbereich. Fahre nach Echo Park die steile unbefestigte Straße nur bei Tageslicht und nach aktuellem NPS-Hinweis. Widersprechen Schilder, Nässe oder Fahrzeugfähigkeit dem Plan, kehre vor dem Abstieg um." },
      "dinosaur-national-monument-observe": { en: "Remain inside the official night-use area, shield red light and keep campground or day-use circulation clear. At Echo Park, respect quiet hours and wildlife around the assigned pitch. A designated setting supports observation without granting access to neighbouring roads or river edges.", de: "Bleibe im offiziellen Nachtbereich, schirme Rotlicht ab und halte Camping- oder Tagesverkehr frei. Beachte in Echo Park Ruhezeiten und Wildtiere am zugewiesenen Platz. Eine ausgewiesene Umgebung trägt Beobachtung, ohne Nachbarstraßen oder Flussränder freizugeben." },
      "dinosaur-national-monument-leave": { en: "Non-campers depart Split Mountain from the day-use parking under current rules; campers remain only at their reserved site. Echo Park campers wait for a safe daylight road departure. Do not finish either session by driving to the other area.", de: "Nichtcamper verlassen Split Mountain vom angrenzenden Tagesparkplatz nach aktueller Regel; Camper bleiben ausschließlich am reservierten Platz. Echo-Park-Camper warten auf eine sichere Tagesabfahrt über die geprüfte Straße. Beende keine Sitzung mit einer Fahrt zum anderen Bereich." },
    } },
    fieldNotes: {
      "dinosaur-national-monument-access-note": { en: "NPS supplies official footprints for Split Mountain viewing and Echo Park camping. Split Mountain distinguishes campsite guests from adjacent day-use parking; Echo Park requires camping access and a separate road decision.", de: "NPS liefert offizielle Flächen für Split-Mountain-Beobachtung und Echo-Park-Camping. Split Mountain trennt Campinggäste vom angrenzenden Tagesparkplatz; Echo Park verlangt Campingzugang und eine getrennte Straßenentscheidung." },
      "dinosaur-national-monument-weather-note": { en: "Rain can make Echo Park's steep unpaved road impassable even when the sky later clears. Check road condition before descent and remain at Split Mountain only if that site was independently selected and its current access is valid.", de: "Regen kann Echo Parks steile unbefestigte Straße unpassierbar machen, auch wenn der Himmel später aufklart. Prüfe den Zustand vor der Abfahrt; bleibe nur dann bei Split Mountain, wenn dieser Ort unabhängig gewählt und aktuell zugänglich ist." },
      "dinosaur-national-monument-light-note": { en: "Both areas combine dark-sky use with camping or day visitors. Prepare lights before arrival, use brief downward red light and avoid vehicle beams across tents, cliffs, roads or the river corridor.", de: "Beide Bereiche verbinden Dark-Sky-Nutzung mit Camping- oder Tagesgästen. Bereite Licht vor der Ankunft vor, nutze kurzes Rotlicht nach unten und vermeide Fahrzeugstrahlen über Zelte, Klippen, Straßen oder Flusskorridor." },
    },
    faq: [
      { question: { en: "Where do non-campers park for Split Mountain stargazing?", de: "Wo parken Nichtcamper für Split-Mountain-Beobachtung?" }, answer: { en: "NPS directs visitors without a campsite to the adjacent day-use parking area near the designated stargazing spot. Use that area under current instructions and depart lawfully after observation. Do not occupy an unassigned campsite or treat day-use parking as overnight accommodation.", de: "NPS verweist Besucher ohne Stellplatz auf den angrenzenden Tagesparkplatz nahe dem ausgewiesenen Beobachtungsort. Nutze ihn nach aktuellen Hinweisen und fahre danach legal ab. Belege keinen unzugewiesenen Campingplatz und behandle Tagesparken nicht als Übernachtung." } },
      { question: { en: "When is Echo Park unsuitable for a stargazing stay?", de: "Wann ist Echo Park für einen Stargazing-Aufenthalt ungeeignet?" }, answer: { en: "Do not use the route when the steep unpaved road is wet, closed or beyond the vehicle's clearance or four-wheel-drive capability. A campsite booking does not guarantee road access. Confirm conditions before descending and postpone rather than attempting a night transfer.", de: "Nutze die Route nicht, wenn die steile unbefestigte Straße nass, gesperrt oder außerhalb der Bodenfreiheits- beziehungsweise Allradfähigkeit des Fahrzeugs liegt. Eine Campingbuchung garantiert keine Zufahrt. Bestätige Bedingungen vor der Abfahrt und verschiebe statt nachts zu wechseln." } },
    ],
  });
}

function reviseMedicineRocks(guide) {
  applyEditorialRevision(guide, {
    standfirst: { en: "Medicine Rocks is an International Dark Sky Sanctuary with a public Night Sky Trail and current evening events, but trail use and camping are separate. Montana FWP publishes the final trail geometry and directs event participants to the signed meeting and viewing area. Campsite 1 is a distinct first-come overnight footprint. Check park hours, event instructions, campsite availability and closures before choosing one plan; never invent a parking point from the trail line.", de: "Medicine Rocks ist ein International Dark Sky Sanctuary mit öffentlichem Night Sky Trail und aktuellen Abendveranstaltungen, doch Wegnutzung und Camping bleiben getrennt. Montana FWP veröffentlicht die endgültige Weggeometrie und verweist Veranstaltungsteilnehmer auf den ausgeschilderten Treff- und Beobachtungsbereich. Campsite 1 ist eine getrennte First-come-Übernachtungsfläche. Prüfe Parkzeiten, Veranstaltungshinweise, Platzverfügbarkeit und Sperren vor der Wahl; erfinde nie einen Parkplatz aus der Weglinie." },
    editorialAngle: { en: "The signed Night Sky Trail is the public astronomy route during valid park access; first-come Campsite 1 is the overnight alternative. Event signage, not a guessed coordinate, determines where a programme begins.", de: "Der ausgeschilderte Night Sky Trail ist bei gültigem Parkzugang die öffentliche Astronomieroute; der zuerst vergebene Campsite 1 ist die Übernachtungsalternative. Veranstaltungsbeschilderung und keine geschätzte Koordinate bestimmt den Programmbeginn." },
    sections: {
      "medicine-rocks-where": { en: ["The catalogue trail record lies on Montana FWP's official Night Sky Trail geometry. Current evening listings identify parking and a viewing area, while the guide deliberately defers to the signed event meeting point on the chosen date. This prevents a line on a GIS map from becoming an unsupported arrival coordinate or permission to park beside fragile rock formations.", "Campsite 1 uses the exact official FWP facility coordinate and is available on a first-come basis rather than through a guaranteed assignment. It supplies an overnight footprint governed by campground quiet hours and park rules. A vacant-looking trail area is not overflow when the campsite is occupied, and a campsite does not authorise night driving to the event area after settling."], de: ["Der Katalogeintrag liegt auf der offiziellen Night-Sky-Trail-Geometrie von Montana FWP. Aktuelle Abendtermine nennen Park- und Beobachtungsbereich; der Guide verweist für das gewählte Datum bewusst auf den ausgeschilderten Treffpunkt. So wird eine GIS-Linie weder zur unbelegten Ankunftskoordinate noch zur Parkerlaubnis neben empfindlichen Felsformationen.", "Campsite 1 nutzt die genaue offizielle FWP-Anlagenkoordinate und wird nach Ankunftsreihenfolge statt durch garantierte Zuweisung vergeben. Er bietet eine Übernachtungsfläche unter Ruhezeiten und Parkregeln. Eine leer wirkende Wegfläche ist bei belegtem Camp kein Ersatz, und ein Campingplatz erlaubt nach dem Einrichten keine Nachtfahrt zur Veranstaltungsfläche."] },
      "medicine-rocks-conditions": { en: ["Read the current FWP page for day-use hours, evening event timing, fees and closures. A sanctuary designation confirms the night-sky context but cannot extend today's gate or trail access. For an event, follow its signed parking and meeting instructions. For independent trail use, finish within the published access conditions and keep the return visible before darkness.", "First-come camping requires a fallback outside the park if Campsite 1 is unavailable; it does not justify sleeping at the trail parking or another facility. Check wind, storms, fire conditions and quiet hours before unpacking. If a programme is cancelled or the trail closes, remain at a lawful campsite only when one is actually occupied under current rules."], de: ["Lies die aktuelle FWP-Seite zu Tageszeiten, Abendtermin, Gebühren und Sperren. Die Sanctuary-Auszeichnung bestätigt den Nachthimmel, verlängert aber keinen heutigen Tor- oder Wegzugang. Folge bei Veranstaltungen den ausgeschilderten Park- und Treffhinweisen. Beende selbstständige Wegnutzung innerhalb der veröffentlichten Bedingungen und erkenne den Rückweg vor der Dunkelheit.", "First-come-Camping benötigt eine Ausweichunterkunft außerhalb des Parks, falls Campsite 1 belegt ist; es rechtfertigt kein Schlafen am Trail-Parkplatz oder einer anderen Anlage. Prüfe Wind, Gewitter, Feuerlage und Ruhezeiten vor dem Auspacken. Fällt ein Programm aus oder schließt der Weg, bleibe nur dann im Park, wenn ein legaler Stellplatz tatsächlich belegt wurde."] },
    },
    tour: { summary: { en: "Use the signed Night Sky Trail under current park hours or a published evening event, following its actual meeting and viewing signs. For an overnight plan, secure first-come Campsite 1 in daylight and observe quietly beside that footprint. Do not merge trail parking and campground use, and leave for accommodation outside the park when no lawful site is available.", de: "Nutze den ausgeschilderten Night Sky Trail innerhalb aktueller Parkzeiten oder bei einer veröffentlichten Abendveranstaltung und folge deren tatsächlichen Treff- und Beobachtungsschildern. Sichere für Übernachtung Campsite 1 bei Tageslicht und beobachte ruhig neben dieser Fläche. Vermische Trail-Parken und Camping nicht und fahre zu Unterkunft außerhalb, wenn kein legaler Platz verfügbar ist." }, suitability: { en: "Suitable for visitors who can follow signed event access or obtain a first-come campsite, respect park and quiet hours and abandon the night without using an improvised parking or camping footprint.", de: "Geeignet für Besucher, die ausgeschildertem Veranstaltungszugang folgen oder einen First-come-Platz erhalten, Park- und Ruhezeiten beachten und ohne improvisierte Park- oder Campingfläche abbrechen können." }, steps: {
      "medicine-rocks-check": { en: "Choose the trail event or Campsite 1 before arrival and read current FWP hours, fees, closure and weather information. For an event, use the published date and expect the on-site sign to resolve the meeting point. For camping, prepare for first-come availability rather than assuming a reservation.", de: "Wähle Trail-Veranstaltung oder Campsite 1 vor der Ankunft und lies aktuelle FWP-Angaben zu Zeiten, Gebühren, Sperre und Wetter. Nutze für eine Veranstaltung das veröffentlichte Datum und lass den Treffpunkt vom Schild vor Ort bestimmen. Plane beim Camping mit First-come-Verfügbarkeit statt angenommener Reservierung." },
      "medicine-rocks-arrive": { en: "Reach the park while trail, campsite and rock boundaries remain visible. Follow the signed event parking or occupy Campsite 1 only if lawfully available. Keep roads and formations clear, and do not turn the trail's mapped geometry into a shortcut or roadside unloading point.", de: "Erreiche den Park, solange Weg, Campingplatz und Felsgrenzen sichtbar sind. Folge dem ausgeschilderten Veranstaltungsparken oder belege Campsite 1 nur bei legaler Verfügbarkeit. Halte Straßen und Formationen frei und mache aus der kartierten Weggeometrie weder Abkürzung noch Straßenentladepunkt." },
      "medicine-rocks-observe": { en: "Remain with the event viewing area or beside the occupied campsite, use low shielded red light and keep quiet around other visitors. The sanctuary protects both dark sky and landscape; it does not make every opening between rocks an astronomy pad.", de: "Bleibe in der Veranstaltungs-Beobachtungsfläche oder neben dem belegten Stellplatz, nutze schwaches abgeschirmtes Rotlicht und verhalte dich gegenüber anderen ruhig. Das Sanctuary schützt Himmel und Landschaft und macht nicht jede Öffnung zwischen Felsen zur Astronomiefläche." },
      "medicine-rocks-leave": { en: "Return along the signed trail within access hours or remain at Campsite 1 until lawful departure under campground rules. If no campsite was obtained, leave the park for the planned external accommodation. Do not sleep at event parking or transfer between facilities after dark.", de: "Kehre auf dem ausgeschilderten Weg innerhalb der Zugangszeiten zurück oder bleibe nach Campingregeln bis zur legalen Abfahrt auf Campsite 1. Wurde kein Platz erhalten, verlasse den Park zur geplanten externen Unterkunft. Schlafe weder am Veranstaltungsparkplatz noch wechsle nachts zwischen Anlagen." },
    } },
    fieldNotes: {
      "medicine-rocks-access-note": { en: "FWP documents the Night Sky Trail, current evening events and exact Campsite 1 facility. Event signs resolve the meeting place; first-come status resolves camping. Neither source supports guessed parking or an unassigned overnight area.", de: "FWP dokumentiert Night Sky Trail, aktuelle Abendtermine und die genaue Anlage Campsite 1. Veranstaltungsschilder bestimmen den Treffort; First-come-Status das Camping. Keine Quelle stützt geschätztes Parken oder unzugewiesene Übernachtungsfläche." },
      "medicine-rocks-weather-note": { en: "Open prairie, rock and first-come camping make wind, storms and fire conditions operational issues. Check the event and park notice for the chosen evening and leave when safe trail use or lawful shelter is uncertain.", de: "Offene Prärie, Fels und First-come-Camping machen Wind, Gewitter und Feuerlage zu Betriebsfragen. Prüfe Veranstaltungs- und Parkhinweis für den Abend und fahre ab, wenn sichere Wegnutzung oder legaler Schutz unklar ist." },
      "medicine-rocks-light-note": { en: "The Night Sky Trail and campground serve a recognised sanctuary. Prepare screens before arrival, use brief downward red light and avoid illuminating rock surfaces, signs, tents or other observers.", de: "Night Sky Trail und Camp gehören zu einem anerkannten Sanctuary. Bereite Displays vor der Ankunft vor, nutze kurzes Rotlicht nach unten und beleuchte weder Felsflächen noch Schilder, Zelte oder andere Beobachter." },
    },
    faq: [
      { question: { en: "Where should an evening event visitor park at Medicine Rocks?", de: "Wo parken Besucher einer Abendveranstaltung in Medicine Rocks?" }, answer: { en: "Use the parking and meeting area signed for that published event. The trail record follows official geometry but intentionally does not invent a parking coordinate from it. Current on-site instructions take precedence over the catalogue map and keep vehicles off unsupported surfaces.", de: "Nutze den für die veröffentlichte Veranstaltung ausgeschilderten Park- und Treffbereich. Der Wegeintrag folgt offizieller Geometrie, leitet daraus aber bewusst keine Parkkoordinate ab. Aktuelle Hinweise vor Ort stehen über der Katalogkarte und halten Fahrzeuge von unbelegten Flächen fern." } },
      { question: { en: "Is Campsite 1 guaranteed for an overnight visit?", de: "Ist Campsite 1 für eine Übernachtung garantiert?" }, answer: { en: "No. FWP identifies it as a first-come campsite. Arrive in daylight with a lawful external accommodation fallback and observe there only after securing the site. A full campsite does not permit sleeping at trail parking or elsewhere inside the park.", de: "Nein. FWP kennzeichnet ihn als First-come-Platz. Komme bei Tageslicht mit legaler externer Unterkunft als Alternative und beobachte dort erst nach Erhalt des Platzes. Ein volles Camp erlaubt kein Schlafen am Trail-Parkplatz oder anderswo im Park." } },
    ],
  });
}

function reviseNewportWisconsin(guide) {
  applyEditorialRevision(guide, {
    standfirst: { en: "Newport State Park welcomes casual stargazers and astronomers, but it is not an all-night shoreline park. Wisconsin DNR lists year-round hours from 06:00 to 23:00 and asks night-sky visitors to scout viewing areas during daylight. Choose one established shoreline setting, learn the return before dusk and leave by closing. A backpack campsite requires a separate reservation and remains accommodation, not permission to beach-hop after dark.", de: "Newport State Park heißt Gelegenheitsbeobachter und Astronomen willkommen, ist aber kein rund um die Uhr offener Uferpark. Wisconsin DNR nennt ganzjährig 06:00 bis 23:00 Uhr und bittet Nachthimmelbesucher, Beobachtungsflächen bei Tageslicht zu erkunden. Wähle einen bestehenden Uferbereich, lerne den Rückweg vor der Dämmerung und verlasse den Park bis zur Schließung. Ein Backpack-Camp benötigt eine getrennte Reservierung und ist Unterkunft statt Erlaubnis zum nächtlichen Strandwechsel." },
    editorialAngle: { en: "The 23:00 closing time shapes every public shoreline session. Daylight scouting is not optional route decoration; it is the DNR method for avoiding an improvised search along Lake Michigan after dark.", de: "Die Schließzeit um 23 Uhr prägt jede öffentliche Ufersitzung. Tageserkundung ist keine optionale Routendekoration, sondern die DNR-Methode gegen improvisierte Suche entlang des Lake Michigan bei Nacht." },
    sections: {
      "newport-wisconsin-where": { en: ["DNR identifies Newport as a Dark Sky Park and astronomy destination without turning the entire Lake Michigan shore into one visitor footprint. Select an established area that can be reached and exited within park hours, scout it in daylight as requested and record the exact return. Stay on public surfaces and avoid moving along unfamiliar beach or forest edges after darkness.", "Backpack camping follows a separate reservation and approach. A booked site provides lawful overnight shelter but does not extend public shoreline hours or create a second observing tour. Carry only equipment compatible with the backpack route, establish the site before dark and decide whether any public viewing stop can still end by 23:00."], de: ["DNR nennt Newport einen Dark Sky Park und ein Astronomieziel, ohne das gesamte Ufer des Lake Michigan zu einer Besucherfläche zu machen. Wähle einen bestehenden Bereich, der innerhalb der Parkzeiten erreicht und verlassen werden kann, erkunde ihn wie verlangt bei Tageslicht und speichere den Rückweg. Bleibe auf öffentlichen Flächen und wechsle nachts nicht entlang unbekannter Strand- oder Waldränder.", "Backpack-Camping folgt einer getrennten Reservierung und Anreise. Ein gebuchter Platz bietet legale Übernachtung, verlängert aber weder öffentliche Uferzeiten noch schafft er eine zweite Beobachtungstour. Trage nur zur Backpack-Route passende Ausrüstung, richte den Platz vor Dunkelheit ein und entscheide, ob ein öffentlicher Beobachtungshalt weiterhin bis 23 Uhr endet."] },
      "newport-wisconsin-conditions": { en: ["The fixed 06:00-to-23:00 schedule gives the night a hard endpoint in every season. Work backward from parking, walking and packing time rather than treating 23:00 as the moment to begin leaving the shore. Check current DNR notices, weather and surface conditions because designation and published hours do not guarantee every trail or viewing area remains usable.", "Lake wind, waves, fog, cold and wet ground can change a shoreline faster than an inland forecast suggests. If the daylight-scouted route becomes doubtful, end early. A campsite reservation provides shelter only at the assigned backpack site; it does not justify a new beach, roadside stop or closed public area after 23:00."], de: ["Der feste Zeitrahmen von 06:00 bis 23:00 Uhr setzt der Nacht in jeder Saison ein hartes Ende. Rechne von Park-, Geh- und Packzeit rückwärts, statt um 23 Uhr erst den Uferaufbruch zu beginnen. Prüfe aktuelle DNR-Hinweise, Wetter und Boden, denn Auszeichnung und veröffentlichte Zeiten garantieren nicht jeden Weg oder Beobachtungsbereich.", "Seewind, Wellen, Nebel, Kälte und nasser Boden verändern das Ufer schneller als eine Binnenprognose vermuten lässt. Wird die bei Tageslicht erkundete Route fraglich, ende früh. Eine Campingreservierung bietet Schutz nur am zugewiesenen Backpack-Platz und rechtfertigt nach 23 Uhr weder neuen Strand noch Straßenhalt oder geschlossenen öffentlichen Bereich."] },
    },
    tour: { summary: { en: "Scout one established Newport viewing area in daylight, return for a compact session and begin the exit early enough to leave by the year-round 23:00 closure. Keep a backpack campsite, when reserved, as a separately established overnight base. Do not move from beach to beach, extend the public visit beyond hours or improvise a shoreline route in darkness.", de: "Erkunde einen bestehenden Newport-Beobachtungsbereich bei Tageslicht, kehre für eine kompakte Sitzung zurück und beginne den Ausgang früh genug für die ganzjährige Schließung um 23 Uhr. Halte einen reservierten Backpack-Platz als getrennt eingerichtete Übernachtungsbasis. Wechsle nicht zwischen Stränden, überschreite keine öffentliche Zeit und improvisiere nachts keinen Uferweg." }, suitability: { en: "Suitable for visitors who can scout and walk the complete route in daylight, keep the astronomy session short enough for the 23:00 exit and separate public viewing from backpack camping.", de: "Geeignet für Besucher, die die vollständige Route bei Tageslicht erkunden, die Astronomiesitzung kurz genug für den Ausgang um 23 Uhr halten und öffentliche Beobachtung vom Backpack-Camping trennen." }, steps: {
      "newport-wisconsin-check": { en: "Read current DNR notices, confirm 06:00-to-23:00 operation and choose one established viewing area. Plan walking, observation, packing and driving backward from closure. If backpacking, verify the campsite separately and do not count it as an extension of public shoreline access.", de: "Lies aktuelle DNR-Hinweise, bestätige den Betrieb von 06:00 bis 23:00 Uhr und wähle einen bestehenden Beobachtungsbereich. Plane Gehen, Beobachten, Packen und Fahren rückwärts ab Schließung. Bestätige Backpack-Camping getrennt und zähle es nicht als Verlängerung öffentlichen Uferzugangs." },
      "newport-wisconsin-arrive": { en: "Scout the parking, path, shoreline footprint and return during daylight, as DNR advises. Come back only on that known route and carry a compact setup. If signs, waves or surfaces have changed, shorten or cancel rather than continuing to another beach.", de: "Erkunde Parkplatz, Weg, Uferfläche und Rückweg bei Tageslicht, wie DNR empfiehlt. Kehre nur auf dieser bekannten Route zurück und trage einen kompakten Aufbau. Haben sich Schilder, Wellen oder Untergrund verändert, verkürze oder sage ab statt zu einem anderen Strand weiterzugehen." },
      "newport-wisconsin-observe": { en: "Remain inside the scouted public surface, keep red light low and avoid disturbing shoreline habitat or other visitors. Watch the departure clock as closely as the sky. The park's Dark Sky status supports astronomy but does not pause closing time.", de: "Bleibe innerhalb der erkundeten öffentlichen Fläche, halte Rotlicht niedrig und störe weder Uferhabitat noch andere Besucher. Beobachte die Abfahrtsuhr genauso aufmerksam wie den Himmel. Der Dark-Sky-Status unterstützt Astronomie, hält aber die Schließzeit nicht an." },
      "newport-wisconsin-leave": { en: "Pack with enough margin to retrace the daylight-scouted path and exit the park by 23:00. Do not use a backpack campsite unless it was separately reserved, and never replace a late departure with sleeping in parking or another shoreline area.", de: "Packe mit genügend Reserve, um den bei Tageslicht erkundeten Weg zurückzugehen und den Park bis 23 Uhr zu verlassen. Nutze Backpack-Camping nur mit getrennter Reservierung und ersetze eine späte Abfahrt nie durch Schlafen am Parkplatz oder einem anderen Uferbereich." },
    } },
    fieldNotes: {
      "newport-wisconsin-access-note": { en: "DNR supports night-sky visits but fixes year-round public hours at 06:00–23:00 and requests daylight scouting. Those conditions define the shoreline plan; a campground reservation remains a separate overnight arrangement.", de: "DNR unterstützt Nachthimmelbesuche, setzt öffentliche Ganzjahreszeiten aber auf 06:00–23:00 Uhr und verlangt Tageserkundung. Diese Bedingungen definieren den Uferplan; eine Campingreservierung bleibt getrennte Übernachtungsregel." },
      "newport-wisconsin-weather-note": { en: "Lake Michigan wind, waves, fog and wet surfaces can invalidate the scouted route. Check shore conditions before each session and preserve enough time to turn back without approaching the 23:00 boundary.", de: "Wind, Wellen, Nebel und nasse Flächen am Lake Michigan können die erkundete Route ungültig machen. Prüfe Uferbedingungen vor jeder Sitzung und bewahre genug Zeit zum Umkehren vor der 23-Uhr-Grenze." },
      "newport-wisconsin-light-note": { en: "Shoreline observation shares dark habitat with other visitors and wildlife. Prepare screens before leaving parking, use brief downward red light and avoid sweeping the water, trees or route with white lamps.", de: "Uferbeobachtung teilt dunkles Habitat mit Besuchern und Wildtieren. Bereite Displays vor dem Parkplatzweg vor, nutze kurzes Rotlicht nach unten und leuchte nicht mit Weißlicht über Wasser, Bäume oder Route." },
    },
    faq: [
      { question: { en: "How late can visitors stargaze at Newport State Park?", de: "Wie lange dürfen Besucher im Newport State Park beobachten?" }, answer: { en: "The park is open from 06:00 to 23:00 year-round. That means visitors must complete the shoreline walk, packing and exit by 23:00, not merely stop observing then. Scout the route during daylight and build a generous return margin.", de: "Der Park ist ganzjährig von 06:00 bis 23:00 Uhr geöffnet. Besucher müssen Uferweg, Packen und Ausgang bis 23 Uhr abschließen und nicht erst dann die Beobachtung beenden. Erkunde die Route bei Tageslicht und plane großzügige Rückkehrreserve." } },
      { question: { en: "Does a backpack campsite allow all-night shoreline use?", de: "Erlaubt ein Backpack-Camp die ganze Nacht am Ufer?" }, answer: { en: "No reviewed source extends public viewing areas beyond park hours through a campsite reservation. The booking provides an assigned overnight footprint reached under camping rules. Keep shoreline viewing within public hours and return to the campsite by the already scouted route.", de: "Keine geprüfte Quelle verlängert öffentliche Beobachtungsflächen durch eine Campingreservierung über Parkzeiten hinaus. Die Buchung bietet eine zugewiesene Übernachtungsfläche nach Campingregeln. Halte Uferbeobachtung in öffentlichen Zeiten und kehre auf der erkundeten Route zum Camp zurück." } },
    ],
  });
}

function reviseAlula(guide) {
  applyEditorialRevision(guide, {
    standfirst: { en: "AlUla has one independently usable managed viewpoint and one operator-only desert experience. Harrat Viewpoint sits at 1,219 metres with free parking, free entry, no booking requirement and published 14:00–22:00 hours; its official page explicitly supports naked-eye and telescope stargazing. Gharameel begins at the Husaak Adventure Centre meeting point and includes operator four-wheel-drive transport to the remote site, but booking is currently marked as coming back soon. Do not travel beyond the meeting point independently.", de: "AlUla besitzt einen selbstständig nutzbaren verwalteten Aussichtspunkt und ein ausschließlich betreibergestütztes Wüstenerlebnis. Harrat Viewpoint liegt auf 1.219 Metern mit kostenlosem Parken und Eintritt, ohne Buchungspflicht und mit veröffentlichten Zeiten von 14:00 bis 22:00 Uhr; die offizielle Seite unterstützt ausdrücklich Beobachtung mit bloßem Auge und Teleskop. Gharameel beginnt am Treffpunkt Husaak Adventure Centre mit Betreiber-Allradtransfer, doch Buchungen sind derzeit als bald wieder verfügbar markiert. Fahre vom Treffpunkt nie selbstständig weiter." },
    editorialAngle: { en: "Harrat is the complete independent evening and ends at 22:00. Gharameel exists only as a dated operator experience whose meeting point is not the observing field and whose booking must actually reopen before use.", de: "Harrat ist der vollständige selbstständige Abend und endet um 22 Uhr. Gharameel existiert nur als datiertes Betreibererlebnis; dessen Treffpunkt ist nicht die Beobachtungsfläche, und die Buchung muss vor Nutzung tatsächlich wieder öffnen." },
    sections: {
      "alula-where": { en: ["Experience AlUla's directions resolve Harrat Viewpoint to a managed visitor footprint rather than a generic volcanic plateau. The page publishes the 1,219-metre elevation, free parking and admission, no booking requirement and a 14:00-to-22:00 operating window. Visitors may use naked-eye viewing or a telescope there, provided the setup remains within the viewpoint and leaves public circulation clear.", "The official Gharameel experience uses Husaak Adventure Centre only as the arrival and departure meeting point. The operator then provides four-wheel-drive transport in both directions to the remote observing setting. Because the product currently says booking is coming back soon, neither the meeting coordinate nor the desert description supports a visit now. Wait for a date-specific sale and follow that transfer."], de: ["Die Anfahrt von Experience AlUla löst Harrat Viewpoint als verwaltete Besucherfläche statt allgemeines Vulkanplateau auf. Die Seite nennt 1.219 Meter Höhe, kostenloses Parken und freien Eintritt, keine Buchungspflicht sowie 14:00 bis 22:00 Uhr. Besucher dürfen mit bloßem Auge oder Teleskop beobachten, solange der Aufbau im Aussichtspunkt bleibt und öffentlichen Verkehr freihält.", "Das offizielle Gharameel-Erlebnis nutzt das Husaak Adventure Centre nur als Ankunfts- und Abfahrtstreffpunkt. Der Betreiber übernimmt danach den Allradtransfer in beide Richtungen zum abgelegenen Beobachtungsort. Weil das Produkt Buchungen derzeit als bald wieder verfügbar kennzeichnet, trägt weder Treffkoordinate noch Wüstenbeschreibung aktuell einen Besuch. Warte auf einen datierten Verkauf und folge diesem Transfer."] },
      "alula-conditions": { en: ["At Harrat, the firm operational boundary is 22:00. Arrive early enough to park, understand the managed footprint and complete telescope packing before closing. Check current hours, wind, dust and temperature on the official page before ascending. Free entry does not mean unrestricted use after the published finish or permission to leave the viewpoint.", "For Gharameel, availability and operator transport are inseparable from weather and access. A future booking will define the date, meeting time, vehicle transfer and return. If the product is unavailable or cancelled, use Harrat only within its own rules or postpone. Never interpret clear skies as permission to self-drive toward the remote reserve."], de: ["Am Harrat setzt 22 Uhr die feste Betriebsgrenze. Komme früh genug zum Parken, Erkennen der verwalteten Fläche und vollständigen Teleskopabbau vor Schließung. Prüfe aktuelle Zeiten, Wind, Staub und Temperatur vor der Auffahrt auf der offiziellen Seite. Freier Eintritt bedeutet weder Nutzung nach Ende noch Erlaubnis, den Aussichtspunkt zu verlassen.", "Bei Gharameel sind Verfügbarkeit und Betreibertransfer untrennbar mit Wetter und Zugang verbunden. Eine künftige Buchung definiert Datum, Treffzeit, Fahrzeugtransfer und Rückkehr. Ist das Produkt nicht verfügbar oder abgesagt, nutze Harrat nur nach eigenen Regeln oder verschiebe. Deute klaren Himmel nie als Erlaubnis zur selbstständigen Fahrt in das abgelegene Reservat."] },
    },
    tour: { summary: { en: "Use Harrat Viewpoint as the independent plan: arrive during published hours, park free in the managed visitor area, observe with eyes or telescope and finish packing before 22:00. Treat Gharameel as a different future operator night only after bookings reopen, beginning and ending with the included four-wheel-drive transfer from Husaak Adventure Centre.", de: "Nutze Harrat Viewpoint als selbstständigen Plan: Komme in veröffentlichten Zeiten an, parke kostenlos im verwalteten Besucherbereich, beobachte mit Augen oder Teleskop und beende den Abbau vor 22 Uhr. Behandle Gharameel erst nach Wiederöffnung der Buchung als getrennte Betreibernacht mit eingeschlossenem Allradtransfer ab und zurück zum Husaak Adventure Centre." }, suitability: { en: "Suitable for visitors who can complete Harrat within the 22:00 closing time or wait for a valid Gharameel booking and remain entirely under its operator transport and programme.", de: "Geeignet für Besucher, die Harrat vollständig bis 22 Uhr abschließen oder auf gültige Gharameel-Buchung warten und vollständig unter Betreibertransfer und Programm bleiben." }, steps: {
      "alula-check": { en: "Verify Harrat's current 14:00–22:00 hours, weather and managed-access notice before travel. If considering Gharameel, require an actual date-specific booking; a coming-soon label is not availability. Save the Husaak point only as a future operator meeting place.", de: "Bestätige vor der Fahrt Harrats aktuelle Zeiten 14:00–22:00 Uhr, Wetter und Zugangshinweis. Für Gharameel brauchst du eine echte datierte Buchung; baldige Rückkehr ist keine Verfügbarkeit. Speichere den Husaak-Punkt nur als künftigen Betreibertreffpunkt." },
      "alula-arrive": { en: "At Harrat, use free visitor parking and identify the viewpoint boundary while light remains. At a future Gharameel event, check in at Husaak and board only the included operator transfer. Never unload astronomy equipment at the meeting point as though it were the remote observing site.", de: "Nutze am Harrat den kostenlosen Besucherparkplatz und erkenne die Aussichtspunktgrenze bei Licht. Checke bei einer künftigen Gharameel-Veranstaltung am Husaak ein und nutze ausschließlich den eingeschlossenen Betreibertransfer. Lade am Treffpunkt nie Astronomieausrüstung aus, als wäre er der abgelegene Beobachtungsort." },
      "alula-observe": { en: "Keep a Harrat telescope or naked-eye session inside the managed footprint, shielding light and sharing the public overlook. At Gharameel, follow the guide and remain with the transported group. Neither format permits wandering onto surrounding desert or reserve land.", de: "Halte Teleskop- oder Freisichtbeobachtung am Harrat innerhalb der verwalteten Fläche, schirme Licht ab und teile die öffentliche Aussicht. Folge in Gharameel dem Guide und bleibe bei der transportierten Gruppe. Kein Format erlaubt Wanderung auf umgebendes Wüsten- oder Reservatland." },
      "alula-leave": { en: "Finish Harrat packing before 22:00 and depart through the managed parking route. For Gharameel, return only in the operator's four-wheel-drive vehicle to Husaak. Do not extend either night with a self-drive desert stop or remain at the meeting point to observe.", de: "Beende den Harrat-Abbau vor 22 Uhr und fahre über die verwaltete Parkroute ab. Kehre von Gharameel ausschließlich im Betreiber-Allradfahrzeug zum Husaak zurück. Verlängere keinen Abend durch selbstständigen Wüstenhalt und beobachte nicht am Treffpunkt weiter." },
    } },
    fieldNotes: {
      "alula-access-note": { en: "Harrat currently supports free independent entry during published hours. Gharameel supports only a booked operator transfer from Husaak, and booking is presently marked as returning soon; the meeting point itself is not an observing venue.", de: "Harrat unterstützt derzeit kostenlosen selbstständigen Eintritt in veröffentlichten Zeiten. Gharameel funktioniert nur mit gebuchtem Betreibertransfer ab Husaak, und die Buchung ist aktuell als bald wiederkehrend markiert; der Treffpunkt ist kein Beobachtungsort." },
      "alula-weather-note": { en: "At 1,219 metres, Harrat can be windy and cooler than lower AlUla. Check dust, wind and temperature as well as sky clarity, and preserve enough time to pack before the fixed 22:00 closure.", de: "Auf 1.219 Metern kann Harrat windiger und kühler als das tiefe AlUla sein. Prüfe Staub, Wind und Temperatur zusätzlich zur Klarheit und bewahre genug Zeit für Abbau vor der festen Schließung um 22 Uhr." },
      "alula-light-note": { en: "Harrat explicitly welcomes telescope use but remains a shared overlook. Prepare vehicle and screens before observing, use shielded red light and avoid illuminating the cliff edge, other visitors or desert beyond the managed footprint.", de: "Harrat begrüßt Teleskopnutzung ausdrücklich, bleibt aber gemeinsame Aussicht. Bereite Fahrzeug und Displays vor, nutze abgeschirmtes Rotlicht und beleuchte weder Klippenrand noch andere Besucher oder Wüste außerhalb der verwalteten Fläche." },
    },
    faq: [
      { question: { en: "Is Harrat Viewpoint open for independent stargazing?", de: "Ist Harrat Viewpoint für selbstständige Sternbeobachtung geöffnet?" }, answer: { en: "The official page currently lists free entry, free parking, no booking requirement, 14:00–22:00 hours and both naked-eye and telescope stargazing. Recheck those details for the date, remain inside the managed viewpoint and complete packing before closing.", de: "Die offizielle Seite nennt derzeit freien Eintritt, kostenloses Parken, keine Buchungspflicht, 14:00–22:00 Uhr sowie Beobachtung mit Augen und Teleskop. Prüfe die Angaben fürs Datum, bleibe in der verwalteten Aussicht und packe vor Schließung vollständig." } },
      { question: { en: "Can visitors drive independently from Husaak to Gharameel?", de: "Können Besucher selbstständig von Husaak nach Gharameel fahren?" }, answer: { en: "No source supports that plan. The official experience starts at Husaak and includes operator four-wheel-drive transport to and from the remote observing area. Booking is currently marked as coming back soon, so wait for a valid product date rather than travelling to the meeting point or desert independently.", de: "Keine Quelle stützt diesen Plan. Das offizielle Erlebnis beginnt am Husaak und umfasst Betreiber-Allradtransfer zum abgelegenen Beobachtungsbereich und zurück. Buchung ist aktuell als bald wieder verfügbar markiert; warte auf ein gültiges Produktdatum statt selbstständig zu Treffpunkt oder Wüste zu fahren." } },
    ],
  });
}

function reviseAchiVillage(guide) {
  applyEditorialRevision(guide, {
    standfirst: { en: "Achi's verified night sky is delivered through two staffed programmes, not village-outskirts access. The 2026–2027 Heavens Sonohara Night Tour reaches a 1,400-metre summit venue only by gondola from the official base. Namiai Park is separate, with its own address, daily hours to 22:00, required admission or deck booking and a guided session every day with an indoor rain fallback. Choose one current ticket and follow that venue's transport and weather decision.", de: "Achis belegter Nachthimmel wird über zwei betreute Programme vermittelt und nicht über Zugang am Dorfrand. Die Heavens Sonohara Night Tour 2026–2027 erreicht eine 1.400 Meter hohe Gipfelanlage ausschließlich per Gondel von der offiziellen Basis. Namiai Park ist getrennt mit eigener Adresse, täglichen Zeiten bis 22 Uhr, erforderlichem Eintritt oder Deck-Buchung und täglicher Führung samt Innenalternative bei Regen. Wähle ein aktuelles Ticket und folge Transport- sowie Wetterentscheidung dieses Ortes." },
    editorialAngle: { en: "Heavens Sonohara is a gondola event whose ticket controls summit access. Namiai is a ground-based staffed facility with a booking and 22:00 boundary. Neither venue acts as overflow for the other.", de: "Heavens Sonohara ist eine Gondelveranstaltung, deren Ticket den Gipfelzugang steuert. Namiai ist eine bodengebundene betreute Anlage mit Buchung und 22-Uhr-Grenze. Kein Ort ist Ausweichfläche des anderen." },
    sections: {
      "achi-village-where": { en: ["The Star Village Achi operator publishes dated 2026–2027 Night Tour sessions and an official base address. Participants check in there and reach the 1,400-metre summit venue only by the programme gondola. The base is an arrival facility, not a substitute observing field, and the summit is not independently reachable before, after or without the ticketed operation.", "Namiai Park publishes its exact address and map, remains open daily to 22:00 and runs a guided stargazing session every day. Admission or a deck booking is required, and an indoor rain fallback changes the programme without opening the grounds for unsupervised use. Its route, staff and finish are completely separate from the Sonohara gondola."], de: ["Der Betreiber Star Village Achi veröffentlicht datierte Night-Tour-Sitzungen 2026–2027 und eine offizielle Basisadresse. Teilnehmer checken dort ein und erreichen die Gipfelanlage auf 1.400 Metern ausschließlich mit der Programmgondel. Die Basis ist eine Ankunftsanlage und kein Ersatzbeobachtungsfeld; der Gipfel ist weder vor noch nach oder ohne Ticketbetrieb selbstständig erreichbar.", "Namiai Park veröffentlicht genaue Adresse und Karte, ist täglich bis 22 Uhr geöffnet und führt jeden Tag eine begleitete Sternbeobachtung durch. Eintritt oder Deck-Buchung ist erforderlich; eine Innenalternative bei Regen ändert das Programm, ohne unbeaufsichtigte Geländenutzung zu öffnen. Route, Personal und Ende sind vollständig von der Sonohara-Gondel getrennt."] },
      "achi-village-conditions": { en: ["For Heavens Sonohara, use the exact dated ticket and operator announcement to confirm gondola operation, meeting time and mountain-weather outcome. Conditions at 1,400 metres can differ from the base. A cancelled lift or programme removes summit access entirely; the correct response is the operator's alternative or postponement, not a drive toward the village outskirts.", "For Namiai, current admission, deck booking and the 22:00 closing boundary control the night. Rain may move the guided experience indoors, which is a valid programme outcome rather than permission to observe outside alone. Complete departure by the facility's instructions and never carry one venue's ticket to the other."], de: ["Nutze für Heavens Sonohara das genaue datierte Ticket und die Betreiberankündigung zur Bestätigung von Gondelbetrieb, Treffzeit und Bergwetterentscheidung. Bedingungen auf 1.400 Metern können von der Basis abweichen. Fällt Lift oder Programm aus, entfällt der Gipfelzugang vollständig; richtig sind Betreiberalternative oder Verschiebung statt Fahrt zum Dorfrand.", "Für Namiai steuern aktueller Eintritt, Deck-Buchung und die 22-Uhr-Grenze die Nacht. Regen kann die Führung nach innen verlegen; das ist ein gültiges Programmergebnis und keine Erlaubnis zur alleinigen Außenbeobachtung. Beende die Abfahrt nach Anlagenhinweis und übertrage nie ein Ticket auf den anderen Ort."] },
    },
    tour: { summary: { en: "Book a dated Heavens Sonohara Night Tour, check in at the official base and use only the programme gondola to reach and leave the 1,400-metre summit. Alternatively, reserve Namiai Park admission or deck access for a different evening and finish by 22:00, accepting its indoor rain fallback. Do not add village outskirts or transfer between programmes.", de: "Buche eine datierte Heavens Sonohara Night Tour, checke an der offiziellen Basis ein und nutze ausschließlich die Programmgondel zum 1.400-Meter-Gipfel und zurück. Reserviere alternativ an einem anderen Abend Eintritt oder Deck in Namiai Park und ende bis 22 Uhr samt Innenalternative bei Regen. Ergänze keinen Dorfrand und wechsle nicht zwischen Programmen." }, suitability: { en: "Suitable for visitors with a current venue-specific ticket who can accept gondola or staff control, mountain weather decisions and the published finish without seeking independent access.", de: "Geeignet für Besucher mit aktuellem ortsspezifischem Ticket, die Gondel- oder Personalsteuerung, Bergwetterentscheidung und veröffentlichtes Ende ohne selbstständige Zugangssuche akzeptieren." }, steps: {
      "achi-village-check": { en: "Choose Sonohara or Namiai before travel and retain its current ticket, date and weather terms. For Sonohara, confirm gondola operation and base check-in. For Namiai, confirm admission or deck booking and the 22:00 finish. Remove any village-outskirts fallback from the plan.", de: "Wähle Sonohara oder Namiai vor der Fahrt und speichere aktuelles Ticket, Datum und Wetterbedingungen. Bestätige für Sonohara Gondelbetrieb und Basis-Check-in, für Namiai Eintritt oder Deck-Buchung sowie Ende um 22 Uhr. Entferne jeden Dorfrand-Ersatz aus dem Plan." },
      "achi-village-arrive": { en: "Reach the exact official base or Namiai address at the booked time and check in before unloading equipment. Board only the scheduled gondola for the summit, or enter only the Namiai area covered by admission. A car park or base coordinate is not an observing site by itself.", de: "Erreiche genaue offizielle Basis oder Namiai-Adresse zur gebuchten Zeit und melde dich vor dem Ausladen an. Nutze nur die planmäßige Gondel zum Gipfel oder betrete ausschließlich den durch Eintritt gedeckten Namiai-Bereich. Parkplatz oder Basiskoordinate ist allein kein Beobachtungsort." },
      "achi-village-observe": { en: "Remain with the summit programme or Namiai guide, follow lighting and equipment instructions and accept an indoor rain fallback. Keep personal screens dim and do not leave the staffed footprint for a darker edge. The programme defines both the experience and safe return.", de: "Bleibe beim Gipfelprogramm oder Namiai-Guide, folge Licht- und Ausrüstungshinweisen und akzeptiere die Innenalternative bei Regen. Dimme persönliche Displays und verlasse die betreute Fläche nicht für einen dunkleren Rand. Das Programm definiert Erlebnis und sichere Rückkehr." },
      "achi-village-leave": { en: "Descend from Sonohara only on the programme gondola and leave the base after check-out. At Namiai, finish and depart by 22:00 under staff instructions. Never continue to the other venue or an unsupported village-edge location after a short or cancelled session.", de: "Fahre von Sonohara ausschließlich mit der Programmgondel hinab und verlasse die Basis nach dem Auschecken. Beende Namiai nach Personalhinweis und fahre bis 22 Uhr ab. Gehe nach kurzer oder abgesagter Sitzung nie zum anderen Ort oder einem unbelegten Dorfrand weiter." },
    } },
    fieldNotes: {
      "achi-village-access-note": { en: "Both verified venues are programme-only. Sonohara requires a dated ticket and gondola; Namiai requires admission or deck booking. Their exact addresses resolve arrival but never support independent parking-lot or outskirts observing.", de: "Beide belegten Orte sind programmgebunden. Sonohara benötigt datiertes Ticket und Gondel; Namiai Eintritt oder Deck-Buchung. Genaue Adressen lösen die Anreise, stützen aber nie selbstständige Parkplatz- oder Dorfrandbeobachtung." },
      "achi-village-weather-note": { en: "The 1,400-metre summit may differ sharply from the base, while Namiai can switch to an indoor rain programme. Follow the selected operator's outcome; favourable valley weather cannot open a cancelled gondola or outdoor deck.", de: "Der 1.400-Meter-Gipfel kann sich stark von der Basis unterscheiden; Namiai kann auf ein Innen-Regenprogramm wechseln. Folge dem Ergebnis des gewählten Betreibers; günstiges Talwetter öffnet weder abgesagte Gondel noch Außendeck." },
      "achi-village-light-note": { en: "Staffed group programmes depend on shared adaptation. Prepare screens before check-in, use only allowed red light and avoid vehicle or phone light at the gondola base, summit and Namiai deck.", de: "Betreute Gruppenprogramme hängen von gemeinsamer Anpassung ab. Bereite Displays vor dem Check-in vor, nutze nur erlaubtes Rotlicht und vermeide Fahrzeug- oder Telefonlicht an Gondelbasis, Gipfel und Namiai-Deck." },
    },
    faq: [
      { question: { en: "Can visitors reach the Heavens Sonohara summit independently?", de: "Können Besucher den Heavens-Sonohara-Gipfel selbstständig erreichen?" }, answer: { en: "The official 2026–2027 programme reaches the 1,400-metre venue only by gondola from the official base. A dated ticket and operating programme are required. If the gondola or tour does not run, there is no supported independent summit or village-outskirts alternative.", de: "Das offizielle Programm 2026–2027 erreicht die Anlage auf 1.400 Metern ausschließlich per Gondel von der Basis. Datiertes Ticket und laufendes Programm sind erforderlich. Fährt Gondel oder Tour nicht, gibt es keinen belegten selbstständigen Gipfel- oder Dorfrand-Ersatz." } },
      { question: { en: "What happens at Namiai Park when it rains?", de: "Was passiert bei Regen im Namiai Park?" }, answer: { en: "The park publishes an indoor fallback for its daily guided stargazing session. Follow that staffed format under the required admission or deck booking and current hours to 22:00. Rain does not authorise unsupervised outdoor access or transfer to Sonohara.", de: "Der Park veröffentlicht für die tägliche geführte Sternbeobachtung eine Innenalternative. Folge diesem betreuten Format unter erforderlichem Eintritt oder Deck-Buchung und aktuellen Zeiten bis 22 Uhr. Regen erlaubt weder unbeaufsichtigten Außenzugang noch Wechsel nach Sonohara." } },
    ],
  });
}

function reviseCoralPinkSandDunes(guide) {
  applyEditorialRevision(guide, {
    standfirst: { en: "Coral Pink Sand Dunes cannot be presented as routine public night access. Utah State Parks currently lists daylight hours and publishes camping, facilities, reservations and current conditions, but the reviewed primary sources neither establish an International Dark Sky designation nor grant ordinary after-dark use. Readers should verify night permission with park management for their date and hold any required campground booking. Without that confirmation, use the park only by day and observe elsewhere lawfully.", de: "Coral Pink Sand Dunes darf nicht als routinemäßig öffentlich nachts zugänglich dargestellt werden. Utah State Parks nennt derzeit Tageslichtzeiten und veröffentlicht Camping, Einrichtungen, Reservierungen sowie aktuelle Bedingungen; die geprüften Primärquellen belegen weder eine International-Dark-Sky-Auszeichnung noch normalen Nachtzugang. Leser sollen die Nachterlaubnis für ihr Datum bei der Parkverwaltung prüfen und nötige Campingbuchung besitzen. Ohne Bestätigung nutze den Park nur tagsüber und beobachte anderswo legal." },
    editorialAngle: { en: "Transparency is the route: daylight-hour publication creates an access blocker that a campground record alone does not solve. No dark-sky designation is claimed, and every night plan depends on current written or direct park confirmation.", de: "Transparenz ist die Route: Veröffentlichte Tageslichtzeiten schaffen einen Zugangsblocker, den ein Campingeintrag allein nicht löst. Es wird keine Dark-Sky-Auszeichnung behauptet; jeder Nachtplan hängt von aktueller schriftlicher oder direkter Parkbestätigung ab." },
    sections: {
      "coral-pink-sand-dunes-where": { en: ["The state-park page identifies the managed park, campground, facilities and reservation system, but its listed hours are daylight hours. That means neither a dune coordinate nor an established day-use surface proves lawful observing after sunset. A reader planning astronomy must first obtain current confirmation that the intended footprint and time are permitted.", "The campground is a potential overnight base only when properly booked and when park management confirms how, or whether, guests may observe after daylight hours. A reservation proves accommodation, not unrestricted dune access. Keep vehicles, OHVs and equipment within the instructions supplied for that visit and never infer permission from an open-looking sand track."], de: ["Die State-Park-Seite identifiziert verwalteten Park, Campingplatz, Einrichtungen und Reservierungssystem, nennt aber Tageslichtzeiten. Deshalb belegt weder eine Dünenkoordinate noch eine bestehende Tagesfläche legale Beobachtung nach Sonnenuntergang. Wer Astronomie plant, muss zuerst aktuell bestätigen lassen, dass beabsichtigte Fläche und Zeit erlaubt sind.", "Der Campingplatz ist nur mit korrekter Buchung und Bestätigung der Parkverwaltung, wie oder ob Gäste nach Tageslicht beobachten dürfen, eine mögliche Übernachtungsbasis. Eine Reservierung belegt Unterkunft und keinen freien Dünenzugang. Halte Fahrzeuge, OHVs und Ausrüstung innerhalb der Besuchshinweise und leite nie aus offen wirkender Sandspur eine Erlaubnis ab."] },
      "coral-pink-sand-dunes-conditions": { en: ["Check current park conditions, closures, weather, OHV rules, reservation status and the exact after-dark permission before travel. If management cannot confirm the intended night use, the plan stops. A clear forecast, campground vacancy or third-party dark-sky claim cannot override the official daylight-hours publication.", "Sand, wind, temperature and vehicle routes change after sunset, but access uncertainty comes first. Arrive in daylight under any confirmed arrangement, identify the allowed footprint and return, and remain there. If conditions or instructions differ, leave or stay only within lawful accommodation; do not walk or drive farther onto dunes seeking darkness."], de: ["Prüfe aktuelle Parklage, Sperren, Wetter, OHV-Regeln, Reservierung und genaue Nachterlaubnis vor der Reise. Kann die Verwaltung die beabsichtigte Nutzung nicht bestätigen, endet der Plan. Klare Prognose, freier Campingplatz oder Dark-Sky-Behauptung Dritter überstimmt die offiziellen Tageslichtzeiten nicht.", "Sand, Wind, Temperatur und Fahrzeugrouten verändern sich nach Sonnenuntergang, doch Zugangsunsicherheit steht zuerst. Komme unter bestätigter Regelung bei Tageslicht an, erkenne erlaubte Fläche und Rückweg und bleibe dort. Weichen Bedingungen oder Hinweise ab, fahre ab oder bleibe nur in legaler Unterkunft; gehe oder fahre nicht weiter auf die Dünen."],
      },
    },
    tour: { summary: { en: "Before any night visit, obtain current park confirmation that after-dark observation is permitted for the intended date and footprint, then hold every required campground reservation and follow OHV, weather and closure rules. Arrive in daylight and remain only where instructed. If confirmation is absent, do not enter for stargazing; daylight park use is the only supported default.", de: "Hole vor jedem Nachtbesuch die aktuelle Parkbestätigung ein, dass Beobachtung für Datum und Fläche nach Einbruch der Dunkelheit erlaubt ist, halte nötige Campingreservierung und befolge OHV-, Wetter- sowie Sperrregeln. Komme bei Tageslicht und bleibe nur im angewiesenen Bereich. Fehlt Bestätigung, betrete den Park nicht zum Stargazing; Tagesnutzung ist der einzig belegte Standard." }, suitability: { en: "Suitable only for visitors who receive current park confirmation and can comply with the exact campground, vehicle, OHV and night-use conditions; otherwise this is a daylight-only destination.", de: "Geeignet nur für Besucher mit aktueller Parkbestätigung, die genaue Camping-, Fahrzeug-, OHV- und Nachtnutzungsbedingungen erfüllen; andernfalls ist dies ein reines Tagesziel." }, steps: {
      "coral-pink-sand-dunes-check": { en: "Read the official daylight-hours notice and current conditions, then ask park management to confirm whether the exact proposed night use is allowed. Verify campground booking and OHV or vehicle rules separately. Do not proceed on the basis of an unverified dark-sky designation.", de: "Lies den offiziellen Tageslichtzeiten-Hinweis und aktuelle Bedingungen und frage die Parkverwaltung, ob die genaue geplante Nachtnutzung erlaubt ist. Bestätige Campingbuchung sowie OHV- oder Fahrzeugregeln getrennt. Fahre nicht auf Grundlage einer unbelegten Dark-Sky-Auszeichnung fort." },
      "coral-pink-sand-dunes-arrive": { en: "Arrive in daylight only after receiving the required permission and booking. Identify the permitted campsite or visitor footprint, routes and closure boundary before dark. If on-site signs conflict with the earlier plan, follow the current park instruction and do not improvise on sand.", de: "Komme nur nach erforderlicher Erlaubnis und Buchung bei Tageslicht an. Erkenne erlaubten Stellplatz oder Besucherbereich, Routen und Sperrgrenze vor der Dunkelheit. Widersprechen Schilder dem früheren Plan, folge dem aktuellen Parkhinweis und improvisiere nicht im Sand." },
      "coral-pink-sand-dunes-observe": { en: "Keep the session inside the specifically confirmed footprint, minimise light and avoid OHV routes, vegetation and moving dunes. A campsite or permission for one area does not authorise roaming. Stop whenever wind, visibility or park instructions make the return uncertain.", de: "Halte die Sitzung innerhalb der ausdrücklich bestätigten Fläche, minimiere Licht und meide OHV-Routen, Vegetation sowie wandernde Dünen. Stellplatz oder Erlaubnis für einen Bereich erlaubt kein Umherziehen. Beende, sobald Wind, Sicht oder Parkhinweis den Rückweg unsicher machen." },
      "coral-pink-sand-dunes-leave": { en: "Depart or return to the booked campsite exactly as the confirmed night arrangement requires. Do not sleep in day-use parking, extend onto another dune or remain after permission ends. Without a lawful overnight booking, complete the exit within the park's instruction.", de: "Fahre ab oder kehre genau nach bestätigter Nachtregel zum gebuchten Camp zurück. Schlafe nicht auf Tagesparkplätzen, erweitere nicht auf andere Düne und bleibe nicht nach Ende der Erlaubnis. Ohne legale Übernachtungsbuchung schließe die Ausfahrt innerhalb der Parkanweisung ab." },
    } },
    fieldNotes: {
      "coral-pink-sand-dunes-access-note": { en: "Official sources currently publish daylight hours and do not substantiate a Dark Sky designation. Night access must therefore be confirmed for the exact visit; a campground listing or map coordinate alone is insufficient.", de: "Offizielle Quellen veröffentlichen derzeit Tageslichtzeiten und belegen keine Dark-Sky-Auszeichnung. Nachtzugang muss daher für den genauen Besuch bestätigt werden; Campingeintrag oder Kartenkoordinate allein genügt nicht." },
      "coral-pink-sand-dunes-weather-note": { en: "Wind can erase tracks and change dune surfaces, while rain and closures affect roads and OHV areas. These live conditions matter only after lawful access is confirmed and can still cancel the visit.", de: "Wind kann Spuren löschen und Dünenflächen verändern; Regen und Sperren betreffen Straßen sowie OHV-Bereiche. Diese Live-Bedingungen zählen erst nach bestätigtem legalem Zugang und können den Besuch weiterhin absagen." },
      "coral-pink-sand-dunes-light-note": { en: "If night use is confirmed, prepare lights in daylight and use brief downward red illumination within the allowed footprint. Avoid beams across dunes, campsites, OHV routes and sensitive vegetation.", de: "Ist Nachtnutzung bestätigt, bereite Licht bei Tageslicht vor und nutze kurzes Rotlicht nach unten innerhalb der erlaubten Fläche. Vermeide Strahlen über Dünen, Camps, OHV-Routen und empfindliche Vegetation." },
    },
    faq: [
      { question: { en: "Is Coral Pink Sand Dunes routinely open for stargazing after dark?", de: "Ist Coral Pink Sand Dunes routinemäßig nach Einbruch der Dunkelheit geöffnet?" }, answer: { en: "The reviewed official page lists daylight hours, so this guide does not assume routine night access. Visitors should obtain current confirmation from park management for their date, footprint and booking. Without that confirmation, use the park only during supported daylight hours.", de: "Die geprüfte offizielle Seite nennt Tageslichtzeiten; dieser Guide nimmt daher keinen routinemäßigen Nachtzugang an. Besucher sollen aktuelle Bestätigung der Parkverwaltung für Datum, Fläche und Buchung einholen. Ohne Bestätigung nutze den Park nur in den belegten Tageszeiten." } },
      { question: { en: "Is Coral Pink an International Dark Sky Park?", de: "Ist Coral Pink ein International Dark Sky Park?" }, answer: { en: "The available primary park sources reviewed for this catalogue do not substantiate that designation, so none is claimed here. Even a future verified designation would describe sky stewardship, not automatically override official hours, camping reservations, OHV rules, weather closures or night-access permission.", de: "Die für diesen Katalog geprüften Primärquellen belegen diese Auszeichnung nicht; deshalb wird sie hier nicht behauptet. Selbst eine künftig belegte Auszeichnung würde Himmelsmanagement beschreiben und weder offizielle Zeiten noch Campingbuchung, OHV-Regeln, Wettersperre oder Nachterlaubnis automatisch überstimmen." } },
    ],
  });
}

function reviseCedarBreaks(guide) {
  applyEditorialRevision(guide, {
    standfirst: { en: "Cedar Breaks is an International Dark Sky Park where NPS says dark skies can be experienced year-round from park overlooks. That invitation remains conditional on same-day road, facility and seasonal status. Sunset View is the independent primary overlook; Point Supreme hosts ranger-led Night Sky Tours when programmes and access operate. Camping and sleeping in vehicles are prohibited outside the campground, so every overlook session needs a lawful return or separate campground reservation.", de: "Cedar Breaks ist ein International Dark Sky Park, an dessen Aussichtspunkten laut NPS ganzjährig dunkler Himmel erlebt werden kann. Diese Einladung bleibt von tagesaktuellen Straßen-, Anlagen- und Saisonbedingungen abhängig. Sunset View ist die selbstständige Hauptaussicht; Point Supreme bietet Ranger-Night-Sky-Tours bei laufendem Programm und Zugang. Camping und Schlafen im Fahrzeug sind außerhalb des Campingplatzes verboten; jede Aussichtssitzung braucht legalen Rückweg oder getrennte Campreservierung." },
    editorialAngle: { en: "Year-round sky opportunity does not mean year-round road access. Sunset View requires an open overlook and safe return; Point Supreme adds a programme check. Neither parking area is accommodation.", de: "Ganzjährige Himmelsmöglichkeit bedeutet keinen ganzjährigen Straßenzugang. Sunset View benötigt offene Aussicht und sicheren Rückweg; Point Supreme zusätzlich Programmprüfung. Keine Parkfläche ist Unterkunft." },
    sections: {
      "cedar-breaks-where": { en: ["NPS directly supports dark-sky viewing from park overlooks, allowing Sunset View to serve as the primary independent visitor setting when its approach and parking are open. Use the established overlook surface, keep railings and circulation clear and decide the return before darkness. The rim beyond the managed area is not an expanded telescope platform.", "Point Supreme is separate because NPS publishes ranger-led Night Sky Tours there. A current programme defines meeting time, parking and staff-controlled use; without one, the area follows ordinary seasonal facility status. The nearby picnic area and campground also retain their own rules. A tour listing never authorises sleeping in the vehicle after the programme."], de: ["NPS unterstützt Dark-Sky-Beobachtung direkt an Parkaussichten; Sunset View kann bei offener Zufahrt und Parkfläche die selbstständige Hauptumgebung sein. Nutze die bestehende Aussicht, halte Geländer und Verkehrsflächen frei und entscheide den Rückweg vor der Dunkelheit. Der Rand außerhalb des verwalteten Bereichs ist keine erweiterte Teleskopplattform.", "Point Supreme ist getrennt, weil NPS dort rangergeführte Night Sky Tours veröffentlicht. Ein aktuelles Programm definiert Treffzeit, Parken und betreute Nutzung; ohne Termin gilt der normale saisonale Anlagenstatus. Nahe Picknickfläche und Campingplatz behalten eigene Regeln. Ein Toureneintrag erlaubt nie das Schlafen im Fahrzeug danach."] },
      "cedar-breaks-conditions": { en: ["Cedar Breaks sits high enough for snow, wind and seasonal road status to control access long after lower routes appear clear. Read same-day NPS conditions for the chosen overlook, facilities and programme. Year-round stargazing language means the sky remains an attraction when access is possible; it does not promise every overlook, road or restroom is open.", "Plan a session short enough for a safe descent or return to a separately reserved campground. Camping and vehicle sleeping are prohibited at ordinary overlooks and parking areas. If snow, closure, fatigue or programme cancellation removes the return, do not begin. Waiting overnight in the car is not an authorised contingency."], de: ["Cedar Breaks liegt hoch genug, dass Schnee, Wind und saisonaler Straßenstatus den Zugang steuern, lange nachdem tiefere Routen frei wirken. Lies tagesaktuelle NPS-Bedingungen für Aussicht, Anlagen und Programm. Ganzjährige Stargazing-Angaben bedeuten, dass der Himmel bei möglichem Zugang attraktiv bleibt, und versprechen nicht jede offene Aussicht, Straße oder Toilette.", "Plane die Sitzung kurz genug für sichere Abfahrt oder Rückkehr zu einem getrennt reservierten Camp. Camping und Schlafen im Fahrzeug sind an normalen Aussichten und Parkflächen verboten. Nimmt Schnee, Sperrung, Müdigkeit oder Programmabsage den Rückweg, beginne nicht. Über Nacht im Auto zu warten ist keine erlaubte Notlösung."] },
    },
    tour: { summary: { en: "Check same-day NPS conditions and use Sunset View as one established overlook when its road and parking are open, or attend a currently published ranger-led Night Sky Tour at Point Supreme. Remain inside the selected visitor footprint and return to lawful accommodation afterward. Never sleep in an overlook vehicle or add another rim stop after dark.", de: "Prüfe tagesaktuelle NPS-Bedingungen und nutze Sunset View als eine bestehende Aussicht bei offener Straße und Parkfläche oder besuche eine aktuell veröffentlichte Ranger-Night-Sky-Tour am Point Supreme. Bleibe in der gewählten Besucherfläche und kehre danach zu legaler Unterkunft zurück. Schlafe nie im Fahrzeug an der Aussicht und ergänze nachts keinen weiteren Randhalt." }, suitability: { en: "Suitable for visitors who can respond to high-elevation road and snow status, finish within the safe return window and keep observing, campground use and ranger programmes as separate arrangements.", de: "Geeignet für Besucher, die auf Höhenstraße und Schneestatus reagieren, innerhalb des sicheren Rückkehrfensters enden und Beobachtung, Camping sowie Rangerprogramme getrennt behandeln." }, steps: {
      "cedar-breaks-check": { en: "Read same-day NPS conditions for roads, Sunset View, Point Supreme, picnic facilities and campground. Select one open overlook or one current Night Sky Tour and confirm lawful accommodation afterward. Do not infer access from the year-round dark-sky description alone.", de: "Lies tagesaktuelle NPS-Bedingungen für Straßen, Sunset View, Point Supreme, Picknickanlagen und Camp. Wähle eine offene Aussicht oder eine aktuelle Night Sky Tour und bestätige legale Unterkunft danach. Leite Zugang nicht allein aus der ganzjährigen Dark-Sky-Beschreibung ab." },
      "cedar-breaks-arrive": { en: "Reach the chosen overlook while road edges, parking and visitor boundaries remain visible. For a Point Supreme tour, check in at the published time and follow ranger parking. If a barrier, snowbank or notice conflicts with the plan, turn back rather than stopping elsewhere on the rim.", de: "Erreiche die gewählte Aussicht, solange Straßenränder, Parken und Besuchergrenzen sichtbar sind. Checke für eine Point-Supreme-Tour zur veröffentlichten Zeit ein und folge Rangerparken. Widerspricht Barriere, Schneewall oder Hinweis dem Plan, kehre um statt anderswo am Rand zu halten." },
      "cedar-breaks-observe": { en: "Stay on the established overlook or with the ranger programme, keep red light shielded and leave paths and railings unobstructed. High-elevation darkness does not permit stepping beyond barriers or moving equipment onto fragile rim ground.", de: "Bleibe auf der bestehenden Aussicht oder beim Rangerprogramm, schirme Rotlicht ab und halte Wege sowie Geländer frei. Dunkelheit in großer Höhe erlaubt weder das Überschreiten von Barrieren noch Ausrüstung auf empfindlichem Randboden." },
      "cedar-breaks-leave": { en: "Pack before cold, wind or fatigue threatens the checked return and drive directly to the campground or lodging. Do not sleep in the vehicle at Sunset View, Point Supreme or another parking area. A tour's finish also ends that programme footprint.", de: "Packe, bevor Kälte, Wind oder Müdigkeit den geprüften Rückweg gefährdet, und fahre direkt zu Camp oder Unterkunft. Schlafe weder an Sunset View noch Point Supreme oder einem anderen Parkplatz im Fahrzeug. Das Tourende beendet auch diese Programmfläche." },
    } },
    fieldNotes: {
      "cedar-breaks-access-note": { en: "NPS supports year-round dark-sky experience from overlooks, subject to actual seasonal access, and publishes tours at Point Supreme. Camping and vehicle sleeping remain prohibited outside the campground regardless of overlook availability.", de: "NPS unterstützt ganzjähriges Dark-Sky-Erleben an Aussichten vorbehaltlich realem Saisonzugang und veröffentlicht Touren am Point Supreme. Camping und Schlafen im Fahrzeug bleiben außerhalb des Campingplatzes unabhängig von Aussichtszugang verboten." },
      "cedar-breaks-weather-note": { en: "High elevation makes snow, wind and temperature decisive even when valleys are clear. Check the selected overlook and return road on the same day, and preserve enough margin to descend before conditions deteriorate.", de: "Große Höhe macht Schnee, Wind und Temperatur entscheidend, auch wenn Täler klar sind. Prüfe gewählte Aussicht und Rückstraße am selben Tag und bewahre genug Reserve für die Abfahrt vor Verschlechterung." },
      "cedar-breaks-light-note": { en: "Overlooks concentrate visitors near roads, railings and ranger groups. Prepare vehicle lamps before parking, use brief downward red light and avoid beams across the amphitheatre, trails or other observers.", de: "Aussichten bündeln Besucher nahe Straßen, Geländern und Rangergruppen. Bereite Fahrzeuglicht vor dem Parken vor, nutze kurzes Rotlicht nach unten und vermeide Strahlen über Amphitheater, Wege oder andere Beobachter." },
    },
    faq: [
      { question: { en: "Are Cedar Breaks overlooks available year-round?", de: "Sind die Cedar-Breaks-Aussichten ganzjährig verfügbar?" }, answer: { en: "NPS says visitors can experience dark skies year-round from park overlooks, but actual road, overlook and facility access remains seasonal and must be checked the same day. Snow or closure can make a particular point unreachable even while the dark-sky opportunity still exists generally.", de: "NPS sagt, Besucher können an Parkaussichten ganzjährig dunklen Himmel erleben; tatsächlicher Straßen-, Aussicht- und Anlagenzugang bleibt saisonal und muss am selben Tag geprüft werden. Schnee oder Sperre kann einen Punkt unerreichbar machen, obwohl die allgemeine Dark-Sky-Möglichkeit besteht." } },
      { question: { en: "Can visitors sleep in a vehicle after stargazing?", de: "Dürfen Besucher nach der Beobachtung im Fahrzeug schlafen?" }, answer: { en: "No. NPS prohibits camping and sleeping in vehicles outside the campground. Reserve a lawful campsite or lodging and preserve a safe return window from the overlook. An open parking area or completed ranger tour does not create overnight accommodation.", de: "Nein. NPS verbietet Camping und Schlafen im Fahrzeug außerhalb des Campingplatzes. Reserviere legales Camp oder Unterkunft und bewahre ein sicheres Rückkehrfenster von der Aussicht. Eine offene Parkfläche oder beendete Rangerführung schafft keine Übernachtungsunterkunft." } },
    ],
  });
}

const revisions = new Map([
  ["attersee-traunsee", reviseAtterseeTraunsee],
  ["grossmugl", reviseGrossmugl],
  ["poloniny", revisePoloniny],
  ["izera", reviseIzera],
  ["javalambre", reviseJavalambre],
  ["sierra-morena", reviseSierraMorena],
  ["monfrague", reviseMonfrague],
  ["sierra-de-gredos", reviseSierraDeGredos],
  ["aigues-tortes", reviseAiguesTortes],
  ["vercors", reviseVercors],
  ["isle-of-sark", reviseIsleOfSark],
  ["richtersveld", reviseRichtersveld],
  ["kangaroo-island", reviseKangarooIsland],
  ["mudgee", reviseMudgee],
  ["fundy", reviseFundy],
  ["enchanted-rock", reviseEnchantedRock],
  ["staunton-river", reviseStauntonRiver],
  ["kissimmee-prairie", reviseKissimmeePrairie],
  ["big-cypress", reviseBigCypress],
  ["lassen-volcanic", reviseLassenVolcanic],
  ["dinosaur-national-monument", reviseDinosaurNationalMonument],
  ["medicine-rocks", reviseMedicineRocks],
  ["newport-wisconsin", reviseNewportWisconsin],
  ["alula", reviseAlula],
  ["achi-village", reviseAchiVillage],
  ["coral-pink-sand-dunes", reviseCoralPinkSandDunes],
  ["cedar-breaks", reviseCedarBreaks],
]);

for (const [destinationId, revise] of revisions) {
  const guide = guides.find((candidate) => candidate.destinationId === destinationId);
  if (!guide) throw new Error(`${destinationId}: destination guide is missing`);
  revise(guide);
}

fs.writeFileSync(file, `${JSON.stringify(guides, null, 2)}\n`);
console.log(`Rewrote ${revisions.size} expanded destination guide(s) with source-specific editorial copy.`);
